/**
 * The reads of the release cockpit (Phase 4 slice 3a; contract ns/release.ts): G-REL per market with this person's
 * acknowledgements, the finished lots and one lot's facts. Every value is the database's (recipe-core 0781, 0782).
 */
import type pg from 'pg';
import type {
  EuImporterView,
  GrelView,
  LotMarketsView,
  LotReleaseSummaryView,
  LotReleaseView,
  ManufacturerReleaseState,
  MarketAddEvaluationView,
  MarketAddOutcome,
  MarketDispositionState,
  MarketDispositionView,
  ReleaseMarket,
} from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import { refusal } from '../../platform/http/refusal.ts';
import { peopleOf, personRef } from '../common/people.ts';

type Db = Pick<pg.Pool, 'query'>;

interface GrelRow {
  lot: string;
  market: ReleaseMarket;
  epoch: string;
  ready: boolean;
  items: { id: string; group: string; title: string; status: 'GREEN' | 'RED' | 'NA'; problem: string | null; evidence: { kind: string; ref: string; label: string }[]; since_review: boolean }[];
}

interface LotRow {
  lot_id: string;
  lot_code: string;
  batch_id: string;
  batch_number: string;
  product_code: string;
  strength: string;
  markets: string[];
  lot_status: string;
  state: ManufacturerReleaseState;
}

interface Facts {
  decision: { decision: 'RELEASED' | 'REJECTED'; person_id: string; role_code: string; us: string; signature_id: string; delegation_id: string | null; reason: string | null; epoch: string; checklist_hash: string } | null;
  justifications: { deviation_id: string; text: string; signature_id: string }[];
  incidents: { incident_id: string; number: string; severity: string; status: string; assessed: boolean }[];
  registration_relevant: { batch_id: string; exception_id: string; title: string; deviation_ref: string | null }[];
  open_investigation_path: boolean;
  validation_batches: { batch_id: string; batch_number: string; purpose: string; outcome: string | null }[];
  post_change: { batch_id: string; batch_number: string; change_record: string; evaluated: boolean }[];
  gates: { release: string[]; reject: string[] };
}

function noLot(lotId: string): Error {
  return refusal(404, { code: 'EBMR-REL-010', kind: 'INVALID_INPUT', whatHappened: 'There is no finished lot with this id.', why: `Lot ${lotId} is no finished lot of a packaging batch.`, whatYouCanDo: ['Open the release queue.'] });
}

/** G-REL of the lot for the market, evaluated now, with the items this person acknowledged at its epoch. */
export async function grelView(db: Db, lotId: string, market: ReleaseMarket, personId: string): Promise<GrelView> {
  const { rows } = await db.query<{ g: GrelRow }>('select recipe.grel_evaluate($1, $2) as g', [lotId, market]);
  const g = rows[0]?.g;
  if (!g) throw noLot(lotId);
  const acked = new Set(
    (await db.query<{ a: string[] }>('select recipe.grel_acknowledged($1, $2, $3, $4) as a', [lotId, market, g.epoch, personId])).rows[0]?.a ?? [],
  );
  return {
    lotId: g.lot,
    market: g.market,
    epoch: g.epoch,
    ready: g.ready,
    items: g.items.map((i) => ({
      id: i.id,
      group: i.group,
      title: i.title,
      status: i.status,
      problem: i.problem,
      evidence: i.evidence,
      sinceReview: i.since_review,
      acknowledged: i.since_review && acked.has(i.id),
    })),
  };
}

function summary(r: LotRow): LotReleaseSummaryView {
  return {
    lotId: r.lot_id,
    lotCode: r.lot_code,
    batchId: r.batch_id,
    batchNumber: r.batch_number,
    productCode: r.product_code,
    strength: r.strength,
    markets: r.markets,
    lotStatus: r.lot_status,
    state: r.state,
  };
}

export async function releaseQueue(db: Db, state?: ManufacturerReleaseState): Promise<LotReleaseSummaryView[]> {
  const { rows } = await db.query<LotRow>('select * from recipe.release_lots()');
  return rows.filter((r) => state === undefined || r.state === state).map(summary);
}

export async function lotRelease(app: AppContext, db: Db, lotId: string, personId: string): Promise<LotReleaseView> {
  const { rows } = await db.query<LotRow>('select * from recipe.release_lots() where lot_id = $1', [lotId]);
  const row = rows[0];
  if (!row) throw noLot(lotId);
  const facts = (await db.query<{ f: Facts }>('select recipe.release_lot_facts($1) as f', [lotId])).rows[0]?.f;
  if (!facts) throw noLot(lotId);
  const grel = await grelView(db, lotId, 'IN', personId);
  const d = facts.decision;
  const people = await peopleOf(db, [d?.person_id]);
  return {
    ...summary(row),
    grel,
    decision: d
      ? {
          decision: d.decision,
          by: personRef(people, d.person_id, d.role_code),
          at: app.formatInstant(d.us),
          signatureId: d.signature_id,
          delegationId: d.delegation_id,
          reason: d.reason,
          epoch: d.epoch,
          checklistHash: d.checklist_hash,
          justifications: facts.justifications.map((j) => ({ deviationId: j.deviation_id, text: j.text, signatureId: j.signature_id })),
        }
      : null,
    incidents: facts.incidents.map((i) => ({ incidentId: i.incident_id, number: i.number, severity: i.severity, status: i.status, assessed: i.assessed })),
    registrationRelevant: facts.registration_relevant.map((r) => ({ batchId: r.batch_id, exceptionId: r.exception_id, title: r.title, deviationRef: r.deviation_ref })),
    openInvestigationPath: facts.open_investigation_path,
    validationBatches: facts.validation_batches.map((b) => ({ batchId: b.batch_id, batchNumber: b.batch_number, purpose: b.purpose, outcome: b.outcome })),
    postChange: facts.post_change.map((b) => ({ batchId: b.batch_id, batchNumber: b.batch_number, changeRecord: b.change_record, evaluated: b.evaluated })),
    gates: {
      release: { ready: facts.gates.release.length === 0, problems: facts.gates.release },
      reject: { ready: facts.gates.reject.length === 0, problems: facts.gates.reject },
    },
    signable: { aggregateType: 'manufacturer_release', release: `${lotId}/RELEASE`, reject: `${lotId}/REJECT` },
  };
}

// ---------------------------------------------------------------------------------------------
// Phase 4 slice 4a: the market dispositions, market-add evaluations and importers (recipe-core 0820 to 0824)
// ---------------------------------------------------------------------------------------------

const micros = (col: string): string => `(extract(epoch from ${col}) * 1000000)::numeric(20, 0)::text`;

interface EvaluationRow {
  subject_kind: 'BATCH' | 'LOT';
  subject_id: string;
  market: ReleaseMarket;
  outcome: MarketAddOutcome;
  items: { id: string; title: string; outcome: MarketAddOutcome; detail: string | null; evidence: { kind: string; ref: string; label: string }[] }[];
}

function evaluationView(e: EvaluationRow): MarketAddEvaluationView {
  return {
    subjectKind: e.subject_kind,
    subjectId: e.subject_id,
    market: e.market,
    outcome: e.outcome,
    items: e.items.map((i) => ({ id: i.id, title: i.title, outcome: i.outcome, detail: i.detail, evidence: i.evidence })),
  };
}

/** The market-add evaluation of a lot or an issued batch for a market, evaluated now (3.3.3). */
export async function marketAddView(db: Db, kind: 'BATCH' | 'LOT', id: string, market: ReleaseMarket): Promise<MarketAddEvaluationView> {
  const { rows } = await db.query<{ e: EvaluationRow }>('select recipe.market_add_evaluate($1, $2, $3) as e', [kind, id, market]);
  const e = rows[0]?.e;
  if (!e || e.items.some((i) => i.id === 'MA.SUBJECT')) {
    throw refusal(404, {
      code: 'EBMR-DSP-011',
      kind: 'INVALID_INPUT',
      whatHappened: `There is no ${kind === 'LOT' ? 'finished lot' : 'issued GMP batch'} with this id.`,
      why: `${kind} ${id} is unknown.`,
      whatYouCanDo: ['Open the release queue.'],
    });
  }
  return evaluationView(e);
}

interface ChangeRow {
  id: string;
  change: 'ADD' | 'REMOVE';
  market: ReleaseMarket;
  subject_kind: 'BATCH' | 'LOT';
  subject_id: string;
  person_id: string;
  us: string;
  signature_id: string;
  change_record: string | null;
  deviation_ref: string | null;
  removed_after_failure: boolean;
  evaluation: EvaluationRow | null;
}

interface CertificationRow {
  id: string;
  source: 'MESSAGE' | 'TRANSCRIBED' | 'IN_SYSTEM';
  outcome: 'CERTIFIED' | 'REJECTED_BY_QP';
  certifier: string;
  mia_number: string;
  certified_us: string;
  importer_code: string | null;
  reference: string;
  verified: boolean;
  person_id: string;
  source_role: string;
  verified_by: string | null;
  reason: string | null;
}

interface UsDecisionRow {
  decision: 'RELEASED' | 'REJECTED';
  person_id: string;
  role_code: string;
  us: string;
  signature_id: string;
  epoch: string;
  checklist_hash: string;
  reason: string | null;
  deviation_id: string | null;
  with_mr: boolean;
}

const gate = (p: string[]): { ready: boolean; problems: string[] } => ({ ready: p.length === 0, problems: p });

/** The US and EU dispositions of the lot: state, G-REL, decision, certifications, market changes and gates. */
export async function lotMarkets(app: AppContext, db: Db, lotId: string, personId: string): Promise<LotMarketsView> {
  const { rows } = await db.query<{ m: ManufacturerReleaseState | null; set: ReleaseMarket[] | null; qp: boolean }>(
    "select recipe.manufacturer_release_state($1) as m, recipe.market_set('LOT', $1) as set, platform.setting_text('release.in_system_qp_certification') = 'ON' as qp",
    [lotId],
  );
  const head = rows[0];
  if (!head?.set) throw noLot(lotId);
  const changes = (
    await db.query<ChangeRow>('select * from recipe.lot_market_changes($1)', [lotId])
  ).rows;
  const decision = (
    await db.query<UsDecisionRow>(
      `select d.decision, d.person_id, d.role_code, ${micros('d.recorded_at')} as us, d.signature_id, d.epoch, d.checklist_hash, d.reason, d.deviation_id,
              d.with_manufacturer_release as with_mr
         from recipe.us_disposition_decision d where d.lot_id = $1`,
      [lotId],
    )
  ).rows[0];
  const certs = (
    await db.query<CertificationRow>('select * from recipe.lot_qp_certifications($1)', [lotId])
  ).rows;
  const people = await peopleOf(db, [decision?.person_id, ...changes.map((c) => c.person_id), ...certs.flatMap((c) => [c.person_id, c.verified_by])]);
  const gates = (
    await db.query<{ release: string[]; reject: string[]; certify: string[] }>(
      "select recipe.us_disposition_gate_problems($1, 'RELEASE') as release, recipe.us_disposition_gate_problems($1, 'REJECT') as reject, recipe.eu_certification_gate_problems($1) as certify",
      [lotId],
    )
  ).rows[0]!;
  const dispositions: MarketDispositionView[] = [];
  for (const market of ['US', 'EU'] as const) {
    const st = (await db.query<{ s: MarketDispositionState | null }>('select recipe.disposition_state($1, $2) as s', [lotId, market])).rows[0]?.s ?? null;
    if (st === null) continue;
    const added = (await db.query<{ a: boolean }>('select recipe.market_added($1, $2) as a', [lotId, market])).rows[0]?.a ?? false;
    const notHere = [`the ${market} disposition is not decided by this act`];
    dispositions.push({
      market,
      state: st,
      grel: st === 'REMOVED' ? null : await grelView(db, lotId, market, personId),
      decision:
        market === 'US' && decision
          ? {
              decision: decision.decision,
              by: personRef(people, decision.person_id, decision.role_code),
              at: app.formatInstant(decision.us),
              signatureId: decision.signature_id,
              epoch: decision.epoch,
              checklistHash: decision.checklist_hash,
              reason: decision.reason,
              deviationId: decision.deviation_id,
              withManufacturerRelease: decision.with_mr,
            }
          : null,
      certifications:
        market === 'EU'
          ? certs.map((c) => ({
              certificationId: c.id,
              source: c.source,
              outcome: c.outcome,
              certifier: c.certifier,
              miaNumber: c.mia_number,
              certifiedAt: app.formatInstant(c.certified_us),
              importerCode: c.importer_code,
              reference: c.reference,
              verified: c.verified,
              recordedBy: personRef(people, c.person_id, c.source_role),
              verifiedBy: c.verified_by ? personRef(people, c.verified_by, '') : null,
              reason: c.reason,
            }))
          : [],
      marketAdd: added && st !== 'REMOVED' ? await marketAddView(db, 'LOT', lotId, market) : null,
      changes: changes
        .filter((c) => c.market === market)
        .map((c) => ({
          changeId: c.id,
          change: c.change,
          market: c.market,
          subjectKind: c.subject_kind,
          subjectId: c.subject_id,
          by: personRef(people, c.person_id, ''),
          at: app.formatInstant(c.us),
          signatureId: c.signature_id,
          changeRecord: c.change_record,
          deviationRef: c.deviation_ref,
          removedAfterFailure: c.removed_after_failure,
          evaluation: c.evaluation ? evaluationView(c.evaluation) : null,
        })),
      inSystemQp: head.qp,
      gates:
        market === 'US'
          ? { release: gate(gates.release), reject: gate(gates.reject), certify: gate(notHere) }
          : { release: gate(notHere), reject: gate(notHere), certify: gate(gates.certify) },
    });
  }
  return { lotId, manufacturerState: head.m ?? 'NOT_READY', markets: head.set, dispositions };
}

/** The EU importers named in technical agreements. */
export async function euImporters(db: Db): Promise<EuImporterView[]> {
  const { rows } = await db.query<{ id: string; code: string; name: string; ta: string; mia: string; fp: string; products: string[] }>(
    `select i.id, i.code, i.name, i.technical_agreement_ref as ta, i.mia_number as mia, i.key_fingerprint as fp,
            coalesce((select array_agg(p.product_code order by p.product_code) from recipe.eu_importer_product p where p.importer_id = i.id), '{}') as products
       from recipe.eu_importer i order by i.code`,
  );
  return rows.map((r) => ({ importerId: r.id, code: r.code, name: r.name, technicalAgreementRef: r.ta, miaNumber: r.mia, keyFingerprint: r.fp, products: r.products }));
}

/**
 * The signed acts of the release (Phase 4 slices 3a and 4a; signable actions RELEASE_ACT and BATCH_MARKET_ACT). Each signs
 * the record the database act works on and runs that act with the signature in the same transaction; the database
 * decides (recipe-core 0781, 0821 to 0824) and a refusal signs nothing (esig/db-acts.ts).
 *
 *   MANUFACTURER_RELEASE   manufacturer_release <lot>/RELEASE        MANUFACTURER_RELEASE   recipe.record_manufacturer_release
 *                          (expectedEpoch; a named delegate cites delegationId, checked by the kernel and again by the act)
 *                          with usExpectedEpoch (D-P4-5): two rows in one ceremony, the companion us_disposition <lot>/RELEASE
 *                          US_DISPOSITION; recipe.record_release_with_us_disposition
 *   MANUFACTURER_REJECT    manufacturer_release <lot>/REJECT         MANUFACTURER_RELEASE   the same act, with the reason
 *   POST_CHANGE_EVALUATE   post_change_evaluation <batch>/<sha256 of the text>      POST_CHANGE_EVALUATED
 *   PPQ_OUTCOME            ppq_outcome <batch>/<outcome>/<sha256 of protocol, LF, text>  VALIDATION_OUTCOME_RECORDED
 *   INVESTIGATION_JUSTIFY  investigation_justification <lot>/IN/<deviation>/<sha256 of the text>  OPEN_INVESTIGATION_JUSTIFIED
 *   US_DISPOSE             us_disposition <lot>/<RELEASE|REJECT>     US_DISPOSITION (QCU)   recipe.record_us_disposition
 *   QP_INTAKE              qp_transcription <lot>/<sha256 of the details>  QP_CERTIFICATION_RECORDED  recipe.record_qp_transcription
 *   QP_INTAKE_VERIFY       qp_transcription_check <intake>           QP_CERTIFICATION_VERIFIED  recipe.verify_qp_transcription
 *   QP_CERTIFY             qp_certification <lot>/<outcome>          QP_CERTIFIED or QP_REJECTED (registered QP, switch on)  recipe.record_qp_certification
 *   MARKET_ADD, MARKET_REMOVE  market_change LOT/<lot>/<ADD|REMOVE>/<market>/<n>   MARKET_ADDED, MARKET_REMOVED  recipe.record_market_change
 *   BATCH_MARKET_ACT       market_change BATCH/<batch>/<ADD|REMOVE>/<market>/<n>  the same, for an issued batch
 *   RECONFIRM              release_suspension <lot>/<market>/RECONFIRM/<n>             RELEASE_RECONFIRMED (AP; expectedEpoch,
 *                          text = the impact assessment)  recipe.record_after_release_decision (slice 5a)
 *   RECALL                 release_suspension <lot>/<market>/RECALL/<n>                RECALLED (AP; reason)
 *   REJECT_AFTER_RELEASE   release_suspension <lot>/<market>/REJECT_AFTER_RELEASE/<n>  REJECTED_AFTER_RELEASE (AP; reason)
 *                          (n, the market's next decision number, is the database's: recipe.release_suspension_next_id)
 *   DISPOSAL               disposal <lot>/<sha256 of the details>   DISPOSAL_RECORDED  recipe.record_disposal; with `disposalId`
 *                          only, DESTRUCTION_WITNESSED on the same record by an independent witness  recipe.witness_disposal
 */
import { createHash } from 'node:crypto';
import type { ReleaseActInput, SignableAction } from '@ebmr/api-contract';
import type pg from 'pg';
import type { AppContext } from '../../platform/context.ts';
import type { DryRunOutcome, SignableActionHandler } from '../../platform/ports.ts';
import { dbActHandler, refusedOutcome, type ActTarget } from '../esig/db-acts.ts';
import { qmsLinkFromEnv, qmsReleaseFetch } from '../integrations/adapters/qms/index.ts';

type ReleaseAct = Extract<SignableAction, { kind: 'RELEASE_ACT' }>;
type BuiltAct =
  | 'MANUFACTURER_RELEASE'
  | 'MANUFACTURER_REJECT'
  | 'POST_CHANGE_EVALUATE'
  | 'PPQ_OUTCOME'
  | 'INVESTIGATION_JUSTIFY'
  | 'US_DISPOSE'
  | 'QP_INTAKE'
  | 'QP_INTAKE_VERIFY'
  | 'QP_CERTIFY'
  | 'MARKET_ADD'
  | 'MARKET_REMOVE'
  | 'RECONFIRM'
  | 'RECALL'
  | 'REJECT_AFTER_RELEASE'
  | 'DISPOSAL';

/** The members each built act uses; any other is refused (422). */
const USES: Readonly<Record<BuiltAct, { needs: readonly (keyof ReleaseActInput)[]; may: readonly (keyof ReleaseActInput)[] }>> = {
  MANUFACTURER_RELEASE: { needs: ['expectedEpoch'], may: ['delegationId', 'usExpectedEpoch'] },
  MANUFACTURER_REJECT: { needs: ['expectedEpoch', 'reason'], may: ['delegationId'] },
  POST_CHANGE_EVALUATE: { needs: ['batchId', 'text'], may: [] },
  PPQ_OUTCOME: { needs: ['batchId', 'outcome', 'protocolRef', 'text'], may: [] },
  INVESTIGATION_JUSTIFY: { needs: ['deviationId', 'text'], may: [] },
  US_DISPOSE: { needs: ['usDecision', 'expectedEpoch'], may: ['reason', 'deviationId'] },
  QP_INTAKE: { needs: ['qpOutcome', 'certification'], may: ['reason'] },
  QP_INTAKE_VERIFY: { needs: ['intakeId'], may: [] },
  QP_CERTIFY: { needs: ['qpOutcome', 'expectedEpoch'], may: ['reason'] },
  MARKET_ADD: { needs: ['market', 'changeRecordId'], may: [] },
  MARKET_REMOVE: { needs: ['market', 'deviationId'], may: [] },
  RECONFIRM: { needs: ['market', 'expectedEpoch', 'text'], may: [] },
  RECALL: { needs: ['market', 'reason'], may: [] },
  REJECT_AFTER_RELEASE: { needs: ['market', 'reason'], may: [] },
  DISPOSAL: { needs: ['disposalRoute', 'disposalQuantity'], may: ['returnTo', 'disposalReference', 'reprocessingRef', 'text'] },
};
/** DISPOSAL by the witness: the recorded destruction only. */
const WITNESS_USES: { needs: readonly (keyof ReleaseActInput)[]; may: readonly (keyof ReleaseActInput)[] } = { needs: ['disposalId'], may: [] };

const isBuilt = (act: ReleaseAct['act']): act is BuiltAct => act in USES;
const sha256 = (text: string): string => createHash('sha256').update(text, 'utf8').digest('hex');

/** As recipe.qp_details_sha256 computes it: the details as entered, trimmed, one per line. */
export function qpDetailsSha256(i: ReleaseActInput): string {
  const c = i.certification;
  return sha256([i.qpOutcome ?? '', c?.certifier ?? '', c?.miaNumber ?? '', c?.certifiedAt ?? '', c?.reference ?? '', i.reason?.text ?? ''].map((x) => x.trim()).join('\n'));
}

/** As recipe.disposal_details_sha256 computes it: the details as entered, trimmed, one per line. */
export function disposalDetailsSha256(i: ReleaseActInput): string {
  return sha256([i.disposalRoute ?? '', i.disposalQuantity ?? '', i.returnTo ?? '', i.disposalReference ?? '', i.reprocessingRef ?? '', i.text ?? ''].map((x) => x.trim()).join('\n'));
}

const isWitness = (a: ReleaseAct): boolean => a.act === 'DISPOSAL' && a.input.disposalId !== undefined;

/** As the database computes them (recipe-core 0781, 0822, 0824): the aggregate ids of the release acts. */
export function releaseActAggregateId(a: ReleaseAct): string {
  const i = a.input;
  switch (a.act) {
    case 'MANUFACTURER_RELEASE':
      return `${a.lotId}/RELEASE`;
    case 'MANUFACTURER_REJECT':
      return `${a.lotId}/REJECT`;
    case 'POST_CHANGE_EVALUATE':
      return `${i.batchId ?? ''}/${sha256((i.text ?? '').trim())}`;
    case 'PPQ_OUTCOME':
      return `${i.batchId ?? ''}/${i.outcome ?? ''}/${sha256(`${(i.protocolRef ?? '').trim()}\n${(i.text ?? '').trim()}`)}`;
    case 'INVESTIGATION_JUSTIFY':
      return `${a.lotId}/IN/${i.deviationId ?? ''}/${sha256((i.text ?? '').trim())}`;
    case 'US_DISPOSE':
      return `${a.lotId}/${i.usDecision ?? ''}`;
    case 'QP_INTAKE':
      return `${a.lotId}/${qpDetailsSha256(i)}`;
    case 'QP_INTAKE_VERIFY':
      return i.intakeId ?? '';
    case 'QP_CERTIFY':
      return `${a.lotId}/${i.qpOutcome ?? ''}`;
    case 'MARKET_ADD':
    case 'MARKET_REMOVE':
      // The sequence is the database's (recipe.market_change_next_id); targetNow reads it.
      return `LOT/${a.lotId}/${a.act === 'MARKET_ADD' ? 'ADD' : 'REMOVE'}/${i.market ?? ''}`;
    case 'RECONFIRM':
    case 'RECALL':
    case 'REJECT_AFTER_RELEASE':
      // The sequence is the database's (recipe.release_suspension_next_id); targetNow reads it.
      return `${a.lotId}/${i.market ?? ''}/${a.act}`;
    case 'DISPOSAL':
      // The witness signs the recorded destruction's record; targetNow reads its id.
      return isWitness(a) ? (i.disposalId ?? '') : `${a.lotId}/${disposalDetailsSha256(i)}`;
    default:
      return a.lotId;
  }
}

function target(a: ReleaseAct): ActTarget {
  const id = releaseActAggregateId(a);
  switch (a.act) {
    case 'MANUFACTURER_RELEASE':
    case 'MANUFACTURER_REJECT':
      return { aggregateType: 'manufacturer_release', aggregateId: id, meaning: 'MANUFACTURER_RELEASE' };
    case 'POST_CHANGE_EVALUATE':
      return { aggregateType: 'post_change_evaluation', aggregateId: id, meaning: 'POST_CHANGE_EVALUATED' };
    case 'PPQ_OUTCOME':
      return { aggregateType: 'ppq_outcome', aggregateId: id, meaning: 'VALIDATION_OUTCOME_RECORDED' };
    case 'INVESTIGATION_JUSTIFY':
      return { aggregateType: 'investigation_justification', aggregateId: id, meaning: 'OPEN_INVESTIGATION_JUSTIFIED' };
    case 'US_DISPOSE':
      return { aggregateType: 'us_disposition', aggregateId: id, meaning: 'US_DISPOSITION' };
    case 'QP_INTAKE':
      return { aggregateType: 'qp_transcription', aggregateId: id, meaning: 'QP_CERTIFICATION_RECORDED' };
    case 'QP_INTAKE_VERIFY':
      return { aggregateType: 'qp_transcription_check', aggregateId: id, meaning: 'QP_CERTIFICATION_VERIFIED', expectedState: 'TRANSCRIBED' };
    case 'QP_CERTIFY':
      return { aggregateType: 'qp_certification', aggregateId: id, meaning: a.input.qpOutcome === 'REJECTED_BY_QP' ? 'QP_REJECTED' : 'QP_CERTIFIED' };
    case 'MARKET_ADD':
    case 'MARKET_REMOVE':
      return { aggregateType: 'market_change', aggregateId: id, meaning: a.act === 'MARKET_ADD' ? 'MARKET_ADDED' : 'MARKET_REMOVED' };
    case 'RECONFIRM':
    case 'RECALL':
    case 'REJECT_AFTER_RELEASE':
      return { aggregateType: 'release_suspension', aggregateId: id, meaning: AFTER_RELEASE_MEANING[a.act] };
    case 'DISPOSAL':
      return isWitness(a)
        ? { aggregateType: 'disposal', aggregateId: id, meaning: 'DESTRUCTION_WITNESSED', expectedState: 'AWAITING_WITNESS' }
        : { aggregateType: 'disposal', aggregateId: id, meaning: 'DISPOSAL_RECORDED' };
    default:
      return { aggregateType: 'manufacturer_release', aggregateId: `${a.lotId}/${String(a.act)}`, meaning: '' };
  }
}

const AFTER_RELEASE_MEANING = { RECONFIRM: 'RELEASE_RECONFIRMED', RECALL: 'RECALLED', REJECT_AFTER_RELEASE: 'REJECTED_AFTER_RELEASE' } as const;

/** An after-release decision's record, with the market's next decision number and its state read now (slice 5a). */
async function afterReleaseTarget(db: pg.Pool | pg.PoolClient, a: ReleaseAct): Promise<ActTarget> {
  const act = a.act as keyof typeof AFTER_RELEASE_MEANING;
  const { rows } = await db.query<{ a: string; s: string | null }>(
    "select recipe.release_suspension_next_id($1, $2, $3) as a, case when $2 = 'IN' then recipe.manufacturer_release_state($1) else recipe.disposition_state($1, $2) end as s",
    [a.lotId, a.input.market ?? '', act],
  );
  return { aggregateType: 'release_suspension', aggregateId: rows[0]!.a, meaning: AFTER_RELEASE_MEANING[act], ...(rows[0]!.s ? { expectedState: rows[0]!.s } : {}) };
}

/** The witness signs the record of the destruction recorded on the lot (slice 5a). */
async function witnessTarget(db: pg.Pool | pg.PoolClient, a: ReleaseAct): Promise<ActTarget> {
  const { rows } = await db.query<{ a: string }>('select aggregate_id as a from recipe.lot_disposal where id = $1 and lot_id = $2', [a.input.disposalId, a.lotId]);
  return { aggregateType: 'disposal', aggregateId: rows[0]?.a ?? `${a.lotId}/no-disposal`, meaning: 'DESTRUCTION_WITNESSED', expectedState: 'AWAITING_WITNESS' };
}

/** A market change's record, with the subject's next sequence number read now. */
async function marketChangeTarget(db: pg.Pool | pg.PoolClient, kind: 'LOT' | 'BATCH', id: string, change: 'ADD' | 'REMOVE', market: string): Promise<ActTarget> {
  const { rows } = await db.query<{ a: string; s: string }>(
    "select recipe.market_change_next_id($1, $2, $3, $4) as a, case when $4 = any (coalesce(recipe.market_set($1, $2), '{}')) then 'IN_SET' else 'NOT_IN_SET' end as s",
    [kind, id, change, market],
  );
  return { aggregateType: 'market_change', aggregateId: rows[0]!.a, meaning: change === 'ADD' ? 'MARKET_ADDED' : 'MARKET_REMOVED', expectedState: rows[0]!.s };
}

function inputRefusal(a: ReleaseAct): DryRunOutcome | null {
  if (!isBuilt(a.act)) {
    return refusedOutcome(501, 'NOT_IMPLEMENTED', 'This release act is not available yet. Nothing was signed.', `${String(a.act)} is not a release act.`, ['IN-05'], ['Use another path for now.']);
  }
  const u = isWitness(a) ? WITNESS_USES : USES[a.act];
  const given = Object.keys(a.input) as (keyof ReleaseActInput)[];
  const extra = given.filter((k) => !u.needs.includes(k) && !u.may.includes(k));
  const missing = u.needs.filter((k) => a.input[k] === undefined);
  if (extra.length === 0 && missing.length === 0) return null;
  const why = [missing.length > 0 ? `needs ${missing.join(', ')}` : '', extra.length > 0 ? `takes no ${extra.join(', ')}` : ''].filter((x) => x !== '').join(' and ');
  return refusedOutcome(422, 'EBMR-API-ACT-INPUT', 'The act does not carry what it needs. Nothing was signed.', `${a.act} ${why}.`, ['DI-37'], ['Reload the screen and sign again.']);
}

export function releaseActHandler(app: AppContext): SignableActionHandler<ReleaseAct> {
  return dbActHandler<ReleaseAct>(app, {
    kind: 'RELEASE_ACT',
    aggregateTypes: ['manufacturer_release', 'post_change_evaluation', 'ppq_outcome', 'investigation_justification', 'us_disposition', 'qp_transcription',
                     'qp_transcription_check', 'qp_certification', 'market_change', 'release_suspension', 'disposal'],
    target,
    targetNow: (db, a) => {
      if (a.act === 'MARKET_ADD' || a.act === 'MARKET_REMOVE') return marketChangeTarget(db, 'LOT', a.lotId, a.act === 'MARKET_ADD' ? 'ADD' : 'REMOVE', a.input.market ?? '');
      if (a.act === 'RECONFIRM' || a.act === 'RECALL' || a.act === 'REJECT_AFTER_RELEASE') return afterReleaseTarget(db, a);
      if (isWitness(a)) return witnessTarget(db, a);
      return Promise.resolve(target(a));
    },
    // D-P4-5: the AP who also holds the QCU permission releases for the US in the same ceremony.
    companionOf: (a) =>
      a.act === 'MANUFACTURER_RELEASE' && a.input.usExpectedEpoch !== undefined
        ? { aggregateType: 'us_disposition', aggregateId: `${a.lotId}/RELEASE`, meaning: 'US_DISPOSITION' }
        : undefined,
    reasonOf: (a) =>
      (a.act === 'MANUFACTURER_REJECT' || a.act === 'US_DISPOSE' || a.act === 'QP_INTAKE' || a.act === 'QP_CERTIFY' || a.act === 'RECALL' || a.act === 'REJECT_AFTER_RELEASE') &&
      a.input.reason
        ? { reasonCode: a.input.reason.code, reasonText: a.input.reason.text }
        : undefined,
    delegationOf: (a) => (a.act === 'MANUFACTURER_RELEASE' || a.act === 'MANUFACTURER_REJECT' ? a.input.delegationId : undefined),
    precheck: (_client, _ctx, a) => Promise.resolve(inputRefusal(a)),
    async apply(client, _ctx, a, signatureId, companionSignatureId) {
      const i = a.input;
      // Phase 6 slice 6a (D-P6a-3): with a QMS integrated, a release fetches the lot's QMS status live inside this signing
      // transaction; the database's release guard requires that answer (recipe-core 0951). Rejections never ask the QMS.
      if (a.act === 'MANUFACTURER_RELEASE' || a.act === 'RECONFIRM' || (a.act === 'US_DISPOSE' && i.usDecision === 'RELEASE') ||
          (a.act === 'QP_CERTIFY' && i.qpOutcome !== 'REJECTED_BY_QP')) {
        await qmsReleaseFetch(client, qmsLinkFromEnv(), a.lotId);
      }
      switch (a.act) {
        case 'MANUFACTURER_RELEASE':
          if (i.usExpectedEpoch !== undefined) {
            if (!companionSignatureId) throw new Error('a two-row release needs its US_DISPOSITION signature');
            await client.query('select recipe.record_release_with_us_disposition($1, $2, $3, $4, $5)', [a.lotId, signatureId, companionSignatureId, i.expectedEpoch, i.usExpectedEpoch]);
            break;
          }
          await client.query("select recipe.record_manufacturer_release($1, 'RELEASE', $2, $3, null)", [a.lotId, signatureId, i.expectedEpoch]);
          break;
        case 'MANUFACTURER_REJECT':
          await client.query("select recipe.record_manufacturer_release($1, 'REJECT', $2, $3, $4)", [a.lotId, signatureId, i.expectedEpoch, i.reason?.text ?? null]);
          break;
        case 'POST_CHANGE_EVALUATE':
          await client.query('select recipe.record_post_change_evaluation($1, $2, $3)', [i.batchId, i.text, signatureId]);
          break;
        case 'PPQ_OUTCOME':
          await client.query('select recipe.record_ppq_outcome($1, $2, $3, $4, $5)', [i.batchId, i.outcome, i.protocolRef, i.text, signatureId]);
          break;
        case 'INVESTIGATION_JUSTIFY':
          await client.query("select recipe.justify_open_investigation($1, 'IN', $2, $3, $4)", [a.lotId, i.deviationId, i.text, signatureId]);
          break;
        case 'US_DISPOSE':
          await client.query('select recipe.record_us_disposition($1, $2, $3, $4, $5, $6)', [a.lotId, i.usDecision, signatureId, i.expectedEpoch, i.reason?.text ?? null, i.deviationId ?? null]);
          break;
        case 'QP_INTAKE': {
          const c = i.certification;
          const { rows } = await client.query<{ id: string }>('select recipe.record_qp_transcription($1, $2, $3, $4, $5, $6, $7, $8) as id', [
            a.lotId, i.qpOutcome, c?.certifier, c?.miaNumber, c?.certifiedAt, c?.reference, i.reason?.text ?? null, signatureId,
          ]);
          return { act: a.act, lotId: a.lotId, intakeId: rows[0]?.id ?? null };
        }
        case 'QP_INTAKE_VERIFY':
          await client.query('select recipe.verify_qp_transcription($1, $2)', [i.intakeId, signatureId]);
          break;
        case 'QP_CERTIFY':
          await client.query('select recipe.record_qp_certification($1, $2, $3, $4, $5)', [a.lotId, i.qpOutcome, signatureId, i.expectedEpoch, i.reason?.text ?? null]);
          break;
        case 'MARKET_ADD':
        case 'MARKET_REMOVE':
          await client.query("select recipe.record_market_change('LOT', $1, $2, $3, $4, $5)", [
            a.lotId, a.act === 'MARKET_ADD' ? 'ADD' : 'REMOVE', i.market, a.act === 'MARKET_ADD' ? i.changeRecordId : i.deviationId, signatureId,
          ]);
          break;
        case 'RECONFIRM':
        case 'RECALL':
        case 'REJECT_AFTER_RELEASE': {
          const { rows } = await client.query<{ id: string }>('select recipe.record_after_release_decision($1, $2, $3, $4, $5, $6) as id', [
            a.lotId, i.market, a.act, signatureId, a.act === 'RECONFIRM' ? i.expectedEpoch : null, a.act === 'RECONFIRM' ? i.text : (i.reason?.text ?? null),
          ]);
          return { act: a.act, lotId: a.lotId, decisionId: rows[0]?.id ?? null };
        }
        case 'DISPOSAL': {
          if (i.disposalId !== undefined) {
            await client.query('select recipe.witness_disposal($1, $2)', [i.disposalId, signatureId]);
            return { act: a.act, lotId: a.lotId, disposalId: i.disposalId };
          }
          const { rows } = await client.query<{ id: string }>('select recipe.record_disposal($1, $2, $3, $4, $5, $6, $7, $8) as id', [
            a.lotId, i.disposalRoute, i.disposalQuantity, i.returnTo ?? null, i.disposalReference ?? null, i.reprocessingRef ?? null, i.text ?? null, signatureId,
          ]);
          return { act: a.act, lotId: a.lotId, disposalId: rows[0]?.id ?? null };
        }
        default:
          throw new Error(`release act ${String(a.act)} is not built`);
      }
      return { act: a.act, lotId: a.lotId };
    },
  });
}

type BatchMarketAct = Extract<SignableAction, { kind: 'BATCH_MARKET_ACT' }>;

/** BATCH_MARKET_ACT: market_change BATCH/<batch>/<ADD|REMOVE>/<market>/<n> (3.3.3; recipe-core 0821). */
export function batchMarketActHandler(app: AppContext): SignableActionHandler<BatchMarketAct> {
  const change = (a: BatchMarketAct): 'ADD' | 'REMOVE' => (a.act === 'MARKET_ADD' ? 'ADD' : 'REMOVE');
  return dbActHandler<BatchMarketAct>(app, {
    kind: 'BATCH_MARKET_ACT',
    aggregateTypes: ['market_change'],
    target: (a) => ({ aggregateType: 'market_change', aggregateId: `BATCH/${a.batchId}/${change(a)}/${a.input.market}`, meaning: a.act === 'MARKET_ADD' ? 'MARKET_ADDED' : 'MARKET_REMOVED' }),
    targetNow: (db, a) => marketChangeTarget(db, 'BATCH', a.batchId, change(a), a.input.market),
    precheck: (_client, _ctx, a) => {
      const ref = a.act === 'MARKET_ADD' ? a.input.changeRecordId : a.input.deviationId;
      const other = a.act === 'MARKET_ADD' ? a.input.deviationId : a.input.changeRecordId;
      if (ref !== undefined && other === undefined) return Promise.resolve(null);
      return Promise.resolve(
        refusedOutcome(422, 'EBMR-API-ACT-INPUT', 'The act does not carry what it needs. Nothing was signed.',
          a.act === 'MARKET_ADD' ? 'A market is added under a change record (changeRecordId), never a deviation.' : 'A market is removed with a linked deviation (deviationId), never a change record.',
          ['DI-37'], ['Reload the screen and sign again.']),
      );
    },
    async apply(client, _ctx, a, signatureId) {
      await client.query('select recipe.record_market_change($1, $2, $3, $4, $5, $6)', [
        'BATCH', a.batchId, change(a), a.input.market, a.act === 'MARKET_ADD' ? a.input.changeRecordId : a.input.deviationId, signatureId,
      ]);
      return { act: a.act, batchId: a.batchId };
    },
  });
}

/**
 * The after-release reads (Phase 4 slice 5a; contract ns/release.ts `suspended`, `afterRelease`): the market states of a
 * released lot, the causes that suspended it, the AP's decisions, the recall-assessment and serial-decommissioning tasks,
 * the ERP stock-block messages, the forward trace and the disposal. Every value and every gate is the database's
 * (recipe-core 0840, site services 0880); the acts are RELEASE_ACT RECONFIRM, RECALL, REJECT_AFTER_RELEASE and DISPOSAL.
 */
import type pg from 'pg';
import type { LotAfterReleaseView, ManufacturerReleaseState, ReleaseMarket, SuspendedLotSummaryView, SuspensionCauseKind } from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import { refusal } from '../../platform/http/refusal.ts';
import { peopleOf, personRef, usOf } from '../common/people.ts';

type Db = Pick<pg.Pool, 'query'>;
const MARKETS: readonly ReleaseMarket[] = ['IN', 'US', 'EU'];

/** Lots with a market RELEASE_SUSPENDED or an open recall-assessment task, oldest open cause first. */
export async function suspendedLots(app: AppContext, db: Db): Promise<SuspendedLotSummaryView[]> {
  const { rows } = await db.query<{
    lot_id: string; lot_code: string; product_code: string; batch_number: string; state: ManufacturerReleaseState; suspended: ReleaseMarket[]; open_task: boolean; us: string;
  }>(
    `with lots as (
       select s.lot_id, min(s.recorded_at) as since from recipe.release_suspension s where s.id = any (recipe.open_suspensions(s.lot_id, s.market)) group by s.lot_id
       union
       select t.lot_id, t.opened_at from recipe.release_task t
        where t.kind = 'RECALL_ASSESSMENT' and not exists (select 1 from recipe.release_task_closure c where c.task_id = t.id))
     select x.lot_id, l.lot_code, f.product_code, f.batch_number, recipe.manufacturer_release_state(x.lot_id) as state,
            array(select m from unnest(array['IN', 'US', 'EU']) m
                   where (m = 'IN' and recipe.manufacturer_release_state(x.lot_id) = 'RELEASE_SUSPENDED')
                      or (m <> 'IN' and recipe.disposition_state(x.lot_id, m) = 'RELEASE_SUSPENDED')) as suspended,
            exists (select 1 from recipe.release_task t where t.lot_id = x.lot_id and t.kind = 'RECALL_ASSESSMENT'
                     and not exists (select 1 from recipe.release_task_closure c where c.task_id = t.id)) as open_task,
            ${usOf('x.since')} as us
       from (select lot_id, min(since) as since from lots group by lot_id) x
       join site.material_lot l on l.id = x.lot_id join site.finished_lot f on f.lot_id = x.lot_id
      order by x.since, x.lot_id`,
  );
  return rows.map((r) => ({
    lotId: r.lot_id, lotCode: r.lot_code, productCode: r.product_code, batchNumber: r.batch_number, manufacturerState: r.state,
    suspendedMarkets: r.suspended, openTask: r.open_task, since: app.formatInstant(r.us),
  }));
}

interface Facts {
  lot_code: string;
  product_code: string;
  batch_number: string;
  state: ManufacturerReleaseState;
  markets: { market: ReleaseMarket; state: string; prior: string | null; reconfirm: string; recall: string; reject: string; p_reconfirm: string[]; p_recall: string[]; p_reject: string[] }[];
  causes: { id: string; market: ReleaseMarket; kind: SuspensionCauseKind; ref: string; label: string; via_kind: 'LOT' | 'BATCH' | 'EQUIPMENT'; via_id: string; prior: string; us: string; covered: boolean; problem: string | null }[];
  decisions: { id: string; market: ReleaseMarket; act: 'RECONFIRM' | 'RECALL' | 'REJECT_AFTER_RELEASE'; to_state: string; person_id: string; role_code: string; us: string; signature_id: string; text: string; epoch: string | null; ids: string[] }[];
  tasks: { id: string; kind: 'RECALL_ASSESSMENT' | 'SERIAL_DECOMMISSIONING'; owner_role: string; us: string; closed_us: string | null }[];
  blocks: { id: string; kind: 'BLOCK' | 'UNBLOCK'; cause_key: string; us: string; delivered_us: string | null }[];
  downstream: { lot_id: string; lot_code: string; state: string }[];
  disposal: {
    id: string; route: 'WITNESSED_DESTRUCTION' | 'REPROCESSING' | 'RETURN'; quantity: string; unit: string; return_to: 'SUPPLIER' | 'CUSTOMER' | null; reference: string | null;
    reprocessing_ref: string | null; text: string | null; aggregate_id: string; person_id: string; role_code: string; us: string; signature_id: string;
    witness_person: string | null; witness_us: string | null; witness_signature: string | null;
  } | null;
  disposal_problem: string | null;
}

export async function lotAfterRelease(app: AppContext, db: Db, lotId: string): Promise<LotAfterReleaseView> {
  const { rows } = await db.query<{ f: Facts | null }>(
    `select case when f.lot_id is null then null else jsonb_build_object(
       'lot_code', l.lot_code, 'product_code', f.product_code, 'batch_number', f.batch_number, 'state', recipe.manufacturer_release_state(f.lot_id),
       'markets', (select coalesce(jsonb_agg(jsonb_build_object(
           'market', m, 'state', case m when 'IN' then recipe.manufacturer_release_state(f.lot_id) else recipe.disposition_state(f.lot_id, m) end,
           'prior', (select s.prior_state from recipe.release_suspension s where s.id = any (recipe.open_suspensions(f.lot_id, m)) limit 1),
           'reconfirm', recipe.release_suspension_next_id(f.lot_id, m, 'RECONFIRM'), 'recall', recipe.release_suspension_next_id(f.lot_id, m, 'RECALL'),
           'reject', recipe.release_suspension_next_id(f.lot_id, m, 'REJECT_AFTER_RELEASE'),
           'p_reconfirm', to_jsonb(recipe.after_release_problems(f.lot_id, m, 'RECONFIRM')), 'p_recall', to_jsonb(recipe.after_release_problems(f.lot_id, m, 'RECALL')),
           'p_reject', to_jsonb(recipe.after_release_problems(f.lot_id, m, 'REJECT_AFTER_RELEASE'))) order by o), '[]'::jsonb)
         from unnest(array['IN', 'US', 'EU']) with ordinality u(m, o) where m = 'IN' or m = any (coalesce(recipe.market_set('LOT', f.lot_id), '{}'))),
       'causes', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'market', s.market, 'kind', s.cause_kind, 'ref', s.cause_ref, 'label', s.label,
           'via_kind', s.via_kind, 'via_id', s.via_id, 'prior', s.prior_state, 'us', ${usOf('s.recorded_at')},
           'covered', not (s.id = any (recipe.open_suspensions(s.lot_id, s.market))),
           'problem', case when s.id = any (recipe.open_suspensions(s.lot_id, s.market)) then recipe.suspension_cause_problem(s.id) end) order by s.recorded_at, s.market), '[]'::jsonb)
         from recipe.release_suspension s where s.lot_id = f.lot_id),
       'decisions', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'market', d.market, 'act', d.act, 'to_state', d.to_state, 'person_id', d.person_id,
           'role_code', d.role_code, 'us', ${usOf('d.recorded_at')}, 'signature_id', d.signature_id, 'text', d.text, 'epoch', d.epoch, 'ids', to_jsonb(d.suspension_ids))
           order by d.recorded_at), '[]'::jsonb) from recipe.after_release_decision d where d.lot_id = f.lot_id),
       'tasks', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'kind', t.kind, 'owner_role', t.owner_role, 'us', ${usOf('t.opened_at')},
           'closed_us', (select ${usOf('c.closed_at')} from recipe.release_task_closure c where c.task_id = t.id)) order by t.opened_at), '[]'::jsonb)
         from recipe.release_task t where t.lot_id = f.lot_id),
       'blocks', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'cause_key', r.cause_key, 'us', ${usOf('r.requested_at')},
           'delivered_us', (select ${usOf('x.delivered_at')} from site.erp_stock_block_delivery x where x.request_id = r.id)) order by r.requested_at), '[]'::jsonb)
         from site.erp_stock_block_request r where r.lot_id = f.lot_id),
       'downstream', (select coalesce(jsonb_agg(jsonb_build_object('lot_id', d.id, 'lot_code', dl.lot_code, 'state', recipe.manufacturer_release_state(d.id)) order by dl.lot_code), '[]'::jsonb)
         from unnest(recipe.genealogy_downstream_lots('LOT', f.lot_id)) d(id) join site.material_lot dl on dl.id = d.id),
       'disposal', (select jsonb_build_object('id', x.id, 'route', x.route, 'quantity', x.quantity::text, 'unit', x.unit, 'return_to', x.return_to, 'reference', x.reference,
           'reprocessing_ref', x.reprocessing_ref, 'text', x.text, 'aggregate_id', x.aggregate_id, 'person_id', x.person_id, 'role_code', x.role_code,
           'us', ${usOf('x.recorded_at')}, 'signature_id', x.signature_id, 'witness_person', w.person_id, 'witness_us', case when w.disposal_id is not null then ${usOf('w.recorded_at')} end,
           'witness_signature', w.signature_id)
         from recipe.lot_disposal x left join recipe.lot_disposal_witness w on w.disposal_id = x.id where x.lot_id = f.lot_id),
       'disposal_problem', recipe.disposal_problem(f.lot_id)) end as f
       from (select 1) one left join site.finished_lot f on f.lot_id = $1 left join site.material_lot l on l.id = f.lot_id`,
    [lotId],
  );
  const f = rows[0]?.f;
  if (!f) {
    throw refusal(404, { code: 'EBMR-REL-010', kind: 'INVALID_INPUT', whatHappened: 'There is no finished lot with this id.', why: `Lot ${lotId} is no finished lot of a packaging batch.`, whatYouCanDo: ['Open the release queue.'] });
  }
  const people = await peopleOf(db, [...f.decisions.map((d) => d.person_id), f.disposal?.person_id, f.disposal?.witness_person]);
  const gate = (p: string[]) => ({ ready: p.length === 0, problems: p });
  const at = (us: string) => app.formatInstant(us);
  const d = f.disposal;
  return {
    lotId,
    lotCode: f.lot_code,
    productCode: f.product_code,
    batchNumber: f.batch_number,
    manufacturerState: f.state,
    markets: f.markets.filter((m) => MARKETS.includes(m.market)).map((m) => ({
      market: m.market,
      state: m.state,
      priorState: m.state === 'RELEASE_SUSPENDED' ? m.prior : null,
      signable: { reconfirm: m.reconfirm, recall: m.recall, rejectAfterRelease: m.reject },
      gates: { reconfirm: gate(m.p_reconfirm), recall: gate(m.p_recall), rejectAfterRelease: gate(m.p_reject) },
    })),
    causes: f.causes.map((c) => ({
      suspensionId: c.id, market: c.market, causeKind: c.kind, causeRef: c.ref, label: c.label, via: { kind: c.via_kind, id: c.via_id }, priorState: c.prior,
      suspendedAt: at(c.us), covered: c.covered, problem: c.problem,
    })),
    decisions: f.decisions.map((x) => ({
      decisionId: x.id, market: x.market, act: x.act, toState: x.to_state, by: personRef(people, x.person_id, x.role_code), at: at(x.us), signatureId: x.signature_id,
      text: x.text, epoch: x.epoch, suspensionIds: x.ids,
    })),
    tasks: f.tasks.map((t) => ({ taskId: t.id, kind: t.kind, ownerRole: t.owner_role, status: t.closed_us ? 'CLOSED' : 'OPEN', openedAt: at(t.us), closedAt: t.closed_us ? at(t.closed_us) : null })),
    stockBlocks: f.blocks.map((b) => ({ requestId: b.id, kind: b.kind, causeKey: b.cause_key, requestedAt: at(b.us), deliveredAt: b.delivered_us ? at(b.delivered_us) : null })),
    downstream: f.downstream.map((x) => ({ lotId: x.lot_id, lotCode: x.lot_code, state: x.state })),
    disposal: d
      ? {
          disposalId: d.id, route: d.route, state: d.route === 'WITNESSED_DESTRUCTION' && !d.witness_signature ? 'AWAITING_WITNESS' : 'RECORDED', quantity: d.quantity, unit: d.unit,
          returnTo: d.return_to, reference: d.reference, reprocessingRef: d.reprocessing_ref, text: d.text, aggregateId: d.aggregate_id,
          performedBy: personRef(people, d.person_id, d.role_code), performedAt: at(d.us), signatureId: d.signature_id,
          witnessedBy: d.witness_person ? personRef(people, d.witness_person, 'WITNESS') : null, witnessedAt: d.witness_us ? at(d.witness_us) : null,
          witnessSignatureId: d.witness_signature,
        }
      : null,
    disposalGate: gate(f.disposal_problem ? [f.disposal_problem] : []),
  };
}

apps/tablets-server/test/release/grel-ta.source:
/**
 * Phase 4 slice 3b (tablets 1161, 1162; recipe-core 0800): the Tablets items of the release gate G-REL for a finished lot
 * of a GMP packaging order and the processing batch it packs, each a database rule read as the application role with a
 * red and a green case; QA's signed verification of a compendial rule set; a packaging master completes only through its
 * secondary packaging step.
 *
 * The processing batch and its packaging order are planned and issued through the routes (real register numbers, so the
 * order's parent is the database's own link). What the items read (step states, entries, registered exceptions,
 * deviations, containers, a printing step in the processing master, a whole-batch reprocessing link) is arranged as test
 * set-up: the commands that write those records are proven by their own slices' tests.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { routes, type SignatureCredentials } from '@ebmr/api-contract';
import { sha256Hex } from '@ebmr/expr';
import { esig, withCommand } from '@ebmr/kernel';
import { openServiceSession } from '@ebmr/test-kit';
import { flow } from '@ebmr/recipe-core';
import { cmd, signatureAuth } from '../../../../packages/kernel/test/esig/helpers.ts';
import type { TestDatabase } from '../../../../packages/kernel/test/support/db.ts';
import { cell, reason } from '../../../../packages/recipe-core/test/lifecycle/support.ts';
import { postOrder } from '../../../../packages/recipe-core/test/lifecycle/gmp-support.ts';
import { actorOfBrowser, personaIn, valueOf } from '../esig/support.ts';
import { codeOf } from '../execution/db-guards-support.ts';
import { asSetup } from '../blocks/compression/plant-support.ts';
import { G21_CONFIG } from '../blocks/packaging/db-support.ts';
import { actorOf, gmpLifecycleWorld, INPUTS, LINE, SITE, startGmpBatchWorld, type GmpBatchWorld } from '../support/gmp-world.ts';

type Json = Record<string, unknown>;
interface Item { id: string; group: string; title: string; status: string; problem: string | null; evidence: { kind: string; ref: string; label: string }[]; since_review: boolean }

let w: GmpBatchWorld;
let db: TestDatabase;
let parentId: string;
let orderId: string;
let lotId: string;
const PACK_SIZE = 'PO-100K';
/** A matcher for a string matching r (typed, for object matchers). */
const like = (r: RegExp): unknown => expect.stringMatching(r);
const SIGNATURES = { perform: { role: 'PRODUCTION_OPERATOR' }, check: { meaning: 'VERIFIED', role: 'PRODUCTION_VERIFIER' } };

function phase(id: string, type: string, config: Json, signatures: Json = SIGNATURES): Json {
  return { kind: 'phase', id, name: `Packing step ${id}`, block: { type, version: '1' }, config, records: [], computes: [], reads: [], consumes: [], produces: [], uses: [], equipment: [], signatures, significant: true, riskClass: 'HIGH' };
}

/** The processing master as a packaging master of the same product: printed materials, cartoning and coded surplus. */
function packagingContent(base: flow.MbrContent): flow.MbrContent {
  const m = JSON.parse(JSON.stringify(base)) as Json;
  const header = m['header'] as Json;
  header['family'] = `${String(header['family'])}-PK`;
  header['recordKind'] = 'PACKAGING';
  header['packType'] = 'ALU-PVC-BLISTER';
  header['batchSizes'] = [{ id: PACK_SIZE, quantity: { value: '100000', unit: '{tbl}' } }];
  const stage = ((((m['procedure'] as Json)['body'] as Json)['children'] as Json[])[0] as Json)['body'] as Json;
  const prep = ((stage['children'] as Json[])[0] as Json)['body'] as Json;
  const tb24 = phase('p-tb24', 'TB-24', {
    unit: 'TEST-LINE-CTN-R1', devices: [{ id: 'CW', kind: 'CHECKWEIGHER' }], examination: { every: { value: '1', unit: 'h' }, inRunSample: '5', endSample: '20' },
    cartonsPerShipper: '20', ssccPrefix: '089012345', printedStep: 'p-g21',
  });
  prep['children'] = [
    {
      kind: 'parallel', id: 'par-pack',
      branches: [
        { id: 'br-g21', name: 'Printed materials', body: phase('p-g21', 'G-21', G21_CONFIG) },
        { id: 'br-tb24', name: 'Cartoning', body: tb24 },
        { id: 'br-destroy', name: 'Coded surplus', body: phase('p-destroy', 'G-23', {}, { perform: { role: 'PRODUCTION_OPERATOR' }, check: { meaning: 'WITNESSED', role: 'PRODUCTION_VERIFIER' } }) },
      ],
    },
    ...(prep['children'] as Json[]),
  ];
  const parsed = flow.parseMbr(m);
  if (!parsed.ok) throw new Error(`the packaging master does not parse: ${JSON.stringify(parsed.problems.slice(0, 3))}`);
  return parsed.mbr;
}

// ------------------------------------------------------------------------------------------------
// Arranged facts (test set-up, triggers off)
// ------------------------------------------------------------------------------------------------

const arrange = (sql: string, params: unknown[] = []): Promise<void> => asSetup(w.gmp, sql, params);

/** Sets step instance `key` of batch `batch` (merged into the stored state). */
async function setStep(batch: string, key: string, step: Json): Promise<void> {
  await arrange(`update recipe.execution_state set state = state || jsonb_build_object('steps', coalesce(state -> 'steps', '{}'::jsonb) || jsonb_build_object($2::text, $3::jsonb))
                  where batch_id = $1`, [batch, key, JSON.stringify(step)]);
}

let entrySeq = 9000;
/** Adds an entry of kind `kind` with `data` at step instance `key` of batch `batch`; its id. */
async function addEntry(batch: string, key: string, kind: string, data: Json): Promise<string> {
  entrySeq += 1;
  const id = `EN-${entrySeq}`;
  await arrange(`update recipe.execution_state set state = state || jsonb_build_object('entries', coalesce(state -> 'entries', '{}'::jsonb) || jsonb_build_object($2::text, $3::jsonb))
                  where batch_id = $1`, [batch, id, JSON.stringify({ id, stepKey: key, kind, data, enteredBy: 'test', recordedAt: '0', recordedSeq: entrySeq })]);
  return id;
}
async function dropEntry(batch: string, id: string): Promise<void> {
  await arrange("update recipe.execution_state set state = jsonb_set(state, '{entries}', (state -> 'entries') - $2::text) where batch_id = $1", [batch, id]);
}

/** Registers exception `type` at step instance `key` of batch `batch` (open); its id. */
async function raise(batch: string, key: string, type: string): Promise<string> {
  const id = `EX-${randomUUID().slice(0, 8)}`;
  await arrange(
    `insert into recipe.exception_register (batch_id, exception_id, row_seq, exception_type, category, severity, title, raising_step_key, raising_step, raised_at, raised_at_us,
                                            raised_by, command_person, mandatory, qa_only, deviation_required, registration_relevant, release_blocking, blocks_until, raised_record, correlation_id)
     values ($1, $2, 1, $3, 'OUT_OF_LIMIT', 'ACTION', $3 || ' (test)', $4, split_part($4, '@', 1), clock_timestamp(), 0, 'BLOCK', gen_random_uuid(), true, false, true, false, true, 'DEVIATION', '{}'::jsonb, gen_random_uuid())`,
    [batch, id, type, key],
  );
  return id;
}

/** A deviation of the site (OPEN); its id and reference. */
async function deviation(): Promise<{ id: string; ref: string }> {
  const id = randomUUID();
  const serial = 10000 + Math.floor(Math.random() * 80000000);
  const ref = `DEV-${SITE}-2026-${serial}`;
  await arrange(`insert into site.deviation (id, ref, site_code, ref_year, ref_serial, kind, title, classification, risk_rationale, raised_by_person, raised_by_account, correlation_id)
                 values ($1, $2, $3, 2026, $4, 'DEVIATION', 'Reconciliation outside its limit (test)', 'MAJOR', 'Counts outside the limit need an investigation', gen_random_uuid(), gen_random_uuid(), gen_random_uuid())`,
    [id, ref, SITE, serial]);
  return { id, ref };
}
async function link(batch: string, exception: string, ref: string): Promise<void> {
  await arrange(`insert into recipe.exception_register_act (batch_id, exception_id, act, row_seq, by_person, by_account, role_code, deviation_ref, correlation_id)
                 values ($1, $2, 'DEVIATION_LINKED', 1, gen_random_uuid(), gen_random_uuid(), 'PRODUCTION_SUPERVISOR', $3, gen_random_uuid())`, [batch, exception, ref]);
}
async function disposition(batch: string, exception: string): Promise<void> {
  await arrange(`insert into recipe.exception_register_act (batch_id, exception_id, act, row_seq, by_person, by_account, role_code, outcome, signature_id, note, correlation_id)
                 values ($1, $2, 'DISPOSITIONED', 1, gen_random_uuid(), gen_random_uuid(), 'QA', 'DEVIATION_RAISED', gen_random_uuid(), 'Investigated under the linked deviation', gen_random_uuid())`, [batch, exception]);
}
async function close(dev: string): Promise<void> {
  await arrange("insert into site.deviation_event (deviation_id, event, signature_id, person_id, account_id) values ($1, 'CLOSED', gen_random_uuid(), gen_random_uuid(), gen_random_uuid())", [dev]);
}
/** Resolves exception `ex` of `batch`: linked to a deviation, dispositioned, and the deviation closed. */
async function resolve(batch: string, ex: string): Promise<void> {
  const d = await deviation();
  await link(batch, ex, d.ref);
  await disposition(batch, ex);
  await close(d.id);
}

/** An output container of `batch` in state `state` (held when `held`); its id. */
async function container(batch: string, state: string, held = false): Promise<{ id: string; label: string }> {
  const id = randomUUID();
  const { rows } = await w.gmp.db.admin.query<{ n: string }>('select batch_number as n from recipe.batch_execution where id = $1', [batch]);
  const label = `OC-${rows[0]?.n.replace(/[^A-Za-z0-9/._-]/g, '') ?? 'X'}-${String(10000 + Math.floor(Math.random() * 89999999))}`;
  await arrange(`insert into plant.output_container (id, label_code, batch_id, batch_number, product_code, strength, stage, quantity_unit, opened_by_person, opened_by_account)
                 values ($1, $2, $3, $4, 'P', 'S', 'COMPRESSION', 'kg', gen_random_uuid(), gen_random_uuid())`, [id, label, batch, rows[0]?.n]);
  await arrange("insert into plant.container_close (container_id, net_quantity, person_id, account_id, basis) values ($1, 10, gen_random_uuid(), gen_random_uuid(), 'TYPED')", [id]);
  await arrange("insert into platform.aggregate_state (aggregate_type, aggregate_id, machine_code, machine_version, state, version) values ('output_container', $1, 'output_container', 1, $2, 1)", [id, state]);
  if (held) {
    const check = randomUUID();
    await arrange("insert into plant.ipc_check (id, batch_id, press_code, result, reference, person_id, account_id) values ($1, $2, 'PRESS-T1', 'FAIL', 'TB11:s@:EN-1', gen_random_uuid(), gen_random_uuid())", [check, batch]);
    await arrange('insert into plant.container_hold (container_id, ipc_check_id, person_id, account_id) values ($1, $2, gen_random_uuid(), gen_random_uuid())', [id, check]);
  }
  return { id, label };
}
const setContainerState = (id: string, state: string): Promise<void> => arrange("update platform.aggregate_state set state = $2 where aggregate_type = 'output_container' and aggregate_id = $1", [id, state]);

// ------------------------------------------------------------------------------------------------
// Reading the gate as the application role
// ------------------------------------------------------------------------------------------------

async function items(market = 'IN'): Promise<Item[]> {
  const { rows } = await w.gmp.db.app.query<{ r: Item[] }>('select tab.grel_edition_items($1, $2) as r', [lotId, market]);
  return rows[0]?.r ?? [];
}
async function item(id: string): Promise<Item> {
  const found = (await items()).find((i) => i.id === id);
  if (!found) throw new Error(`no item ${id}`);
  return found;
}

/** A real COMPENDIAL_RULE_SET_VERIFIED signature of the QA approver over rule set `code` version `version`; its id. */
async function signVerification(code: string, version: number): Promise<string> {
  const qa = await actorOf(w.gmp, 'approver');
  const content = await esig.contentForSigning(w.gmp.db.admin, 'compendial_rule_set', `${code}:${version}`);
  const ch = await withCommand(db.app, await cmd(db, qa), (c) =>
    esig.createChallenge(c, { aggregateType: 'compendial_rule_set', aggregateId: `${code}:${version}`, contentVersion: content.contentVersion ?? '1', meaning: 'COMPENDIAL_RULE_SET_VERIFIED', clientContentHash: content.contentHash ?? '' }),
  );
  const authEventId = await signatureAuth(db, qa, qa, ch.challengeId);
  const key = w.gmp.built.ctx.sealKey;
  if (!key) throw new Error('no seal key');
  const r = await withCommand(db.app, await cmd(db, qa), (c) => esig.sign(c, { challengeId: ch.challengeId, authEventId, expectedState: content.state ?? null }, key));
  return r.signatureId;
}

beforeAll(async () => {
  w = await startGmpBatchWorld();
  db = { name: w.gmp.database, admin: w.gmp.db.admin, app: w.gmp.db.app, drop: () => Promise.resolve() };
  const issuer = await w.gmp.asPersona('issuer');
  parentId = await w.issued(issuer);
  const world = await gmpLifecycleWorld(w.gmp);
  const packContent = packagingContent(w.content);
  const v = await world.approvedVersion(packContent);
  await world.authorise({ versionId: v.versionId, market: 'IN', kind: 'CURRENT', cells: [cell(SITE, LINE, PACK_SIZE)], regulatoryBasis: 'IN: registration on file' });
  const steward = await actorOf(w.gmp, 'steward');
  await world.run(steward, (c) =>
    c.query('select site.define_batch_number_rule($1::jsonb)', [
      JSON.stringify({ rule_code: `P-${randomUUID().slice(0, 8).toUpperCase()}`, site_code: SITE, product_code: packContent.header.product.code, batch_kind: 'PACKAGING', format: '{PARENT}/P{SEQ:2}', site_zone: 'Asia/Kolkata', reason: 'Numbering SOP-QA-017 rev 3' }),
    ]),
    reason('packaging numbering rule for the test'),
  );
  const orderNo = await postOrder(w.gmp.db.app, await openServiceSession(w.gmp.db, w.gmp.seed, 'erpInterface'), packContent, PACK_SIZE);
  const planned = valueOf(await issuer.call(routes.planning.planPackagingOrder, { body: { familyId: v.familyId, markets: ['IN'], site: SITE, line: LINE, batchSize: PACK_SIZE, erpOrder: orderNo, parentBatchId: parentId } }));
  orderId = planned.batchId;
  const preview = valueOf(await issuer.call(routes.esig.content, { query: { aggregateType: 'batch_issue', aggregateId: orderId, intent: 'ISSUED' } }));
  const action = { kind: 'GMP_BATCH_ISSUE' as const, batchId: orderId, reason: { code: 'PRODUCTION_PLAN', text: 'Packaging order issued for the plan' }, variants: {}, inputs: INPUTS };
  const challenge = valueOf(
    await issuer.call(routes.esig.createChallenge, { body: { aggregateType: 'batch_issue', aggregateId: orderId, contentVersion: preview.contentVersion, meaning: 'ISSUED', clientContentHash: sha256Hex(preview.canonicalText), action } }),
  );
  const password: SignatureCredentials = { kind: 'PASSWORD', loginName: personaIn(w.gmp, 'issuer').loginName, password: personaIn(w.gmp, 'issuer').password };
  const sign = { challengeId: challenge.challengeId, credentials: password, action };
  valueOf(await issuer.call(routes.esig.sign, { body: { ...sign, proof: await issuer.proof('POST', '/api/esig/sign', sign) } }));
  // The finished lot of the order, 40 packs, as the edition's definer posts it (tab.post_finished_lot is proven in slice 2b).
  const stores = await w.gmp.asPersona('stores');
  lotId = await withCommand(w.gmp.db.admin, { ...(await actorOfBrowser(w.gmp, stores, 'stores')), correlationId: randomUUID() }, async (c) =>
    (await c.query<{ id: string }>('select site.create_finished_lot($1::jsonb) as id', [
      JSON.stringify({ batchId: orderId, batchNumber: planned.batchNumber, edition: 'TABLETS', siteCode: SITE, productCode: packContent.header.product.code, productName: 'Test tablets',
                       strength: packContent.header.product.strength, markets: ['IN'], quantity: '40', unit: 'packs', expiresAt: '2029-06-30T23:59:59Z' }),
    ])).rows[0]?.id ?? '',
  );
  // The order's packing steps as they stand when its record is complete: completed, with an end-of-run examination that
  // passed, the packs reconciled and two full shippers of 20 packs.
  for (const s of ['p-g21', 'p-tb24', 'p-destroy']) await setStep(orderId, `${s}@`, { step: s, status: 'COMPLETED', frames: [] });
  await addEntry(orderId, 'p-tb24@', 'EXAMINATION', { stream: 'EXAM', timing: 'IN_RUN', examined: '5', defective: '0', labelCorrect: true, result: 'PASS' });
  await addEntry(orderId, 'p-tb24@', 'SHIPPER', { sscc: '089012345000000017', packs: '20', part: false });
  await addEntry(orderId, 'p-tb24@', 'SHIPPER', { sscc: '089012345000000024', packs: '20', part: false });
}, 900_000);

afterAll(async () => {
  await w?.close();
});

describe('the Tablets items of G-REL (slice 3b, tablets 1162)', () => {
  it('[INV-05][IN-05] "since review" of a Tablets item reads its own batches and evidence only: changes to other batches, lots, containers and deviations after the review do not count; its own do (tab.grel_changed_since)', async () => {
    const admin = w.gmp.db.admin;
    const changed = async (rev: string | null, batches: string[], ev: unknown[]): Promise<boolean> =>
      (await admin.query<{ r: boolean }>('select tab.grel_changed_since($1::timestamptz, $2::uuid[], $3::jsonb) as r', [rev, batches, JSON.stringify(ev)])).rows[0]!.r;
    const rev = (await admin.query<{ t: string }>('select clock_timestamp()::text as t')).rows[0]!.t;
    const [lotA, lotB, conA, conB, devA, devB, batchX] = Array.from({ length: 7 }, () => randomUUID());
    // TEST FIXTURE: evidence changed after `rev` on other subjects (epoch bumps), and the parent's record touched.
    const fx = await admin.connect();
    try {
      await fx.query('begin');
      await fx.query("set local session_replication_role = 'replica'");
      for (const [kind, id] of [['BATCH', batchX], ['LOT', lotB], ['CONTAINER', conB], ['DEVIATION', devB]] as const) await fx.query('select recipe.bump_epoch($1, $2)', [kind, id]);
      await fx.query('update recipe.execution_state set updated_at = clock_timestamp() where batch_id = $1', [parentId]);
      await fx.query('commit');
    } finally {
      fx.release();
    }
    const own = [{ kind: 'BATCH', ref: orderId }, { kind: 'LOT', ref: lotA }, { kind: 'CONTAINER', ref: conA }, { kind: 'DEVIATION', ref: devA }];
    expect(await changed(rev, [orderId], own)).toBe(false);
    expect(await changed(null, [parentId], own)).toBe(false);
    expect(await changed(rev, [], [{ kind: 'NOTE', ref: 'free text' }])).toBe(false);
    expect(await changed(rev, [parentId], [])).toBe(true);
    for (const e of [{ kind: 'BATCH', ref: parentId }, { kind: 'BATCH', ref: batchX }, { kind: 'LOT', ref: lotB }, { kind: 'CONTAINER', ref: conB },
                     { kind: 'DEVIATION', ref: devB }, { kind: 'CONTAINER', ref: 'not-an-id' }, { kind: 'LOT', ref: 'not-an-id' }, { kind: 'DEVIATION', ref: 'not-an-id' }]) {
      expect(await changed(rev, [], [e]), JSON.stringify(e)).toBe(true);
    }
  });

  it('[INV-05][IN-05] the evidence set of a packaging order\'s lot is the order and its processing parent, in that order (recipe.release_batches)', async () => {
    const { rows } = await w.gmp.db.app.query<{ r: string[] }>('select recipe.release_batches($1) as r', [lotId]);
    expect(rows[0]!.r).toEqual([orderId, parentId]);
    // G3.EXTRA_TESTING reads every batch of the set: an extra test decided for the parent only is found.
    // TEST FIXTURE: QC's extra-testing decisions as site services' command writes them (proven there); the later one clears it.
    const decide = async (decision: 'EXTRA_TESTS' | 'NONE_REQUIRED'): Promise<void> => {
      const fx = await w.gmp.db.admin.connect();
      try {
        await fx.query('begin');
        await fx.query("set local session_replication_role = 'replica'");
