                        select id, batch_number, 'TABLETS', $2, $3, $4, gen_random_uuid(), gen_random_uuid(), gen_random_uuid() from recipe.batch_execution where id = $1`,
                       [parentId, SITE, decision, decision === 'EXTRA_TESTS' ? ['XTRA'] : []]);
