    expect(await item('E.RULE_SETS_VERIFIED')).toMatchObject({ status: 'RED', problem: like(/cannot determine the rule sets entry .* cites: its rule-set reference is malformed/) });
    await dropEntry(parentId, bad);
    const notArray = await addEntry(parentId, 'p-ipc@', 'WEIGHT_CHECK', { check: 'EN-3', ruleSets: 'IP-UOW' });
    expect((await item('E.RULE_SETS_VERIFIED')).status).toBe('RED');
    await dropEntry(parentId, notArray);
  });

  it('[IN-37][PR-45] E.PRINTED_TABLETS_QC: a library call whose element is not pinned is red ("cannot determine"); a printing step inlined from a pinned element needs the hold point after it in that element, under a valid signature', async () => {
    await setParentContent(`jsonb_set(${contentOfParent}, '{procedure,body}', jsonb_build_object('kind', 'sequence', 'id', 'seq-lib', 'children',
                              jsonb_build_array(jsonb_build_object('kind', 'libraryCall', 'id', 'call-print', 'element', 'LIB-PRINT', 'bind', '{}'::jsonb),
                                                ${contentOfParent} #> '{procedure,body}')))`);
    expect(await item('E.PRINTED_TABLETS_QC')).toMatchObject({ status: 'RED', problem: like(/cannot determine whether the processing batch prints/) });
    await setParentContent(`jsonb_set(${contentOfParent}, '{library}', coalesce(${contentOfParent} -> 'library', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
                              'ref', 'LIB-PRINT', 'level', 'OPERATION', 'symbols', '[]'::jsonb, 'body', jsonb_build_object('kind', 'sequence', 'id', 'seq-lprint', 'children', jsonb_build_array(
                                jsonb_build_object('kind', 'phase', 'id', 'p-lprint', 'block', jsonb_build_object('type', 'TB-19', 'version', '1')),
                                jsonb_build_object('kind', 'holdPoint', 'id', 'H-LPRINT', 'name', 'QC approval', 'role', 'QA', 'dispositions', jsonb_build_array('APPROVED', 'REJECTED')))))))`);
    await setStep(parentId, 'call-print/p-lprint@', { step: 'call-print/p-lprint', status: 'COMPLETED', frames: [] });
    expect(await item('E.PRINTED_TABLETS_QC')).toMatchObject({ status: 'RED', problem: 'the tablets printed at call-print/p-lprint@ wait for the QC approval at hold point call-print/H-LPRINT under a valid signature (IN-37)' });
    const signature = await signVerification('LEGACY-UOW', 1);
    await setStep(parentId, 'call-print/H-LPRINT@', { step: 'call-print/H-LPRINT', status: 'COMPLETED', frames: [], disposition: { positive: true, value: 'APPROVED' }, signatures: [{ role: 'HOLD_POINT', valid: true, id: signature }] });
    expect(await item('E.PRINTED_TABLETS_QC')).toMatchObject({ status: 'GREEN', problem: null });
  });

  it('[IN-17][PR-39] E.RECONCILIATION_PRINTED: when the packaging master prints but the record holds no G-21 step instance it is red, never NA', async () => {
    const saved = (await w.gmp.db.admin.query<{ s: Json | null }>("select state -> 'steps' -> 'p-g21@' as s from recipe.execution_state where batch_id = $1", [orderId])).rows[0]?.s;
    await arrange("update recipe.execution_state set state = jsonb_set(state, '{steps}', (state -> 'steps') - 'p-g21@') where batch_id = $1", [orderId]);
    expect(await item('E.RECONCILIATION_PRINTED')).toMatchObject({ status: 'RED', problem: 'the packaging master prints, but the record holds no printed-materials step (G-21): nothing was reconciled' });
    await setStep(orderId, 'p-g21@', saved ?? { step: 'p-g21', status: 'COMPLETED', frames: [] });
    expect((await item('E.RECONCILIATION_PRINTED')).status).toBe('GREEN');
  });

  it('[INV-05][DI-37] since_review: false before QA reviewed the packaging record and for facts older than the review; true on an item whose facts changed after it (an exception, a container state)', async () => {
    expect((await items()).every((i) => !i.since_review)).toBe(true);
    await arrange(`insert into recipe.batch_review_act (batch_id, cycle, act, signature_id, person_id, account_id, role_code, correlation_id)
                   values ($1, recipe.batch_review_cycle($1), 'QA_REVIEWED', gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'QA', gen_random_uuid())`, [orderId]);
    // Facts recorded in the earlier tests are older than the review: nothing to acknowledge for the packs reconciliation.
    expect((await item('E.RECONCILIATION_PACKS')).since_review).toBe(false);
    const ex = await raise(orderId, 'p-tb24@', 'PACK_RECONCILIATION');
    expect(await item('E.RECONCILIATION_PACKS')).toMatchObject({ status: 'RED', since_review: true });
    await resolve(orderId, ex);
    expect(await item('E.RECONCILIATION_PACKS')).toMatchObject({ status: 'GREEN', since_review: true });
    // A container packed into the order released again after the review.
    expect((await item('E.CONTAINER_RELEASE')).since_review).toBe(false);
    const packed = (await item('E.CONTAINER_RELEASE')).evidence[0]?.ref ?? '';
    await arrange("update platform.aggregate_state set state = 'RELEASED_BY_QA', updated_at = clock_timestamp() where aggregate_type = 'output_container' and aggregate_id = $1", [packed]);
    expect(await item('E.CONTAINER_RELEASE')).toMatchObject({ status: 'GREEN', since_review: true });
  });
});

apps/tablets-server/test/release/after-r.source:
/**
 * After release over HTTP (Phase 4 slice 5a; contract ns/release.ts `suspended`, `afterRelease`, RELEASE_ACT RECONFIRM,
 * RECALL, REJECT_AFTER_RELEASE and DISPOSAL; recipe-core 0840, site services 0880): a deviation linked to a released lot
 * suspends it in the linking transaction (the views show the cause, the AP's open task and the ERP stock block), and the
 * AP recalls it through the ceremony, the lot register moving with it; the rules themselves are proven in recipe-core's
 * after-release tests.
 *
 * Fixture, not proof: the manufacturer release is arranged as its act leaves it (its decision row and the lot's transition in
 * one transaction), as in qp-shipping-routes.test.ts. The signed acts need the ceremony mapping of release_suspension and disposal
 * (tab.kernel_signing_meanings, re-created once by slice 5b in tablets 1199): they run once that mapping is installed.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { routes, type ReleaseActInput, type SignableAction } from '@ebmr/api-contract';
import { sha256Hex } from '@ebmr/expr';
import { withCommand } from '@ebmr/kernel';
import { personaIn, refusalOf, tapFor, valueOf } from '../esig/support.ts';
import { actorOf, startGmpBatchWorld, type GmpBatchWorld } from '../support/gmp-world.ts';
import type { TestBrowser } from '../support/harness.ts';
import { credentialsOf, describeAction, signAction } from '../support/signed-acts.ts';

let w: GmpBatchWorld;
let ap: TestBrowser;
let lotId: string;
let downLot: string;
let mapped = false;

beforeAll(async () => {
  w = await startGmpBatchWorld();
  const issuer = await w.gmp.asPersona('issuer');
  ap = await w.gmp.asPersona('qcuAuthoriser');
  const batchId = await w.issued(issuer);
  const number = (await w.gmp.db.admin.query<{ n: string }>('select batch_number as n from recipe.batch_execution where id = $1', [batchId])).rows[0]!.n;
  const stores = await actorOf(w.gmp, 'stores');
  lotId = await withCommand(w.gmp.db.admin, { ...stores, correlationId: randomUUID() }, async (c) =>
    (await c.query<{ id: string }>('select site.create_finished_lot($1::jsonb) as id', [
      JSON.stringify({ batchId, batchNumber: number, edition: 'TABLETS', siteCode: 'SITE-1', productCode: w.content.header.product.code, productName: 'After-release product',
                       strength: '500 mg', markets: ['IN', 'US'], quantity: '1000', unit: 'units', expiresAt: '2029-06-30T23:59:59Z' }),
    ])).rows[0]!.id,
  );
  // A second batch consumed the lot (the genealogy edge, a fixture as in recipe-core's after-release tests); its finished lot is downstream.
  const batch2 = await w.issued(issuer);
  const number2 = (await w.gmp.db.admin.query<{ n: string }>('select batch_number as n from recipe.batch_execution where id = $1', [batch2])).rows[0]!.n;
  downLot = await withCommand(w.gmp.db.admin, { ...stores, correlationId: randomUUID() }, async (c) =>
    (await c.query<{ id: string }>('select site.create_finished_lot($1::jsonb) as id', [
      JSON.stringify({ batchId: batch2, batchNumber: number2, edition: 'TABLETS', siteCode: 'SITE-1', productCode: w.content.header.product.code, productName: 'After-release product',
                       strength: '500 mg', markets: ['IN'], quantity: '1000', unit: 'units', expiresAt: '2029-06-30T23:59:59Z' }),
    ])).rows[0]!.id,
  );
  const fx = await w.gmp.db.admin.connect();
  try {
    await fx.query('begin');
    await fx.query("set local session_replication_role = 'replica'");
    await fx.query(`insert into site.lot_consumption (lot_id, reservation_id, batch_id, batch_number, edition, material_code, quantity, unit, quantity_before, quantity_after, market_set,
                                                      identity_basis, consumed_by_person, consumed_by_account, xact_id)
                    values ($1, gen_random_uuid(), $2, $3, 'TABLETS', 'REWORK', 1, 'units', 10, 9, '{IN}', 'INTERMEDIATE', $4, $4, txid_current())`, [lotId, batch2, number2, randomUUID()]);
    await fx.query('commit');
  } finally {
    fx.release();
  }
  const apActor = await actorOf(w.gmp, 'qcuAuthoriser');
  await withCommand(w.gmp.db.admin, { ...apActor, correlationId: randomUUID() }, async (c) => {
    await c.query('alter table recipe.manufacturer_release_decision disable trigger zzzn_notify_departments');
    await c.query(`insert into recipe.manufacturer_release_decision (lot_id, decision, signature_id, epoch, checklist, checklist_hash, content_hash, person_id, account_id, role_code, correlation_id)
             values ($1, 'RELEASED', gen_random_uuid(), repeat('0', 64), '{"items": []}', repeat('0', 64), 'fixture', $2, $3, 'AUTHORISED_PERSON', gen_random_uuid())`, [lotId, apActor.personId, apActor.accountId]);
    // The lot register moves as the act moves it (material_lot v3 needs a continuous history for the later recall).
    await c.query("select site.lot_transition(l, 'MANUFACTURER_RELEASE', s.version, null, null) from site.material_lot l join platform.aggregate_state s on s.aggregate_type = 'material_lot' and s.aggregate_id = l.id where l.id = $1", [lotId]);
    await c.query('alter table recipe.manufacturer_release_decision enable trigger zzzn_notify_departments');
  });
  mapped = (await w.gmp.db.admin.query<{ m: boolean }>("select 'RECALLED' = any (tab.kernel_signing_meanings('release_suspension')) as m")).rows[0]!.m;
}, 600_000);
afterAll(async () => {
  await w?.close();
});

/** The ceremony of a kiosk persona (the witness on the shop floor): the challenge is confirmed by the persona's own badge tap. */
async function kioskSign(b: TestBrowser, key: string, action: SignableAction) {
  const d = await describeAction(b, action);
  const preview = await b.call(routes.esig.content, { query: { aggregateType: d.aggregateType, aggregateId: d.aggregateId, intent: d.meaning ?? '' } });
  if (!preview.ok) return preview;
  const body = { aggregateType: d.aggregateType, aggregateId: d.aggregateId, contentVersion: preview.value.contentVersion, meaning: d.meaning ?? '', clientContentHash: sha256Hex(preview.value.canonicalText), action };
  const challenge = await b.call(routes.esig.createChallenge, { body, attribution: await tapFor(b, personaIn(w.gmp, key), 'POST', '/api/esig/challenges', body) });
  if (!challenge.ok) return challenge;
  const signBody = { challengeId: challenge.value.challengeId, credentials: credentialsOf(w.gmp, key), action };
  return b.call(routes.esig.sign, { body: { ...signBody, proof: await b.proof('POST', '/api/esig/sign', signBody) } });
}

const view = async () => valueOf(await ap.call(routes.release.afterRelease, { params: { lotId } }));
const recall = (input: ReleaseActInput): SignableAction => ({ kind: 'RELEASE_ACT', act: 'RECALL', lotId, input });

describe('after release over HTTP (slice 5a; L-19, IN-29)', () => {
  it('[L-19][IN-29] a deviation linked after the release suspends the lot at once; the views show the cause, the AP\'s task, the ERP block and the gates', async () => {
    let v = await view();
    expect(v.manufacturerState).toBe('RELEASED');
    expect(v.causes).toEqual([]);
    expect(v.markets.map((m) => [m.market, m.gates.recall.ready, m.gates.reconfirm.ready])).toEqual([['IN', true, false], ['US', false, false]]);
    expect(v.markets[0]!.state).toBe('RELEASED');
    expect(v.downstream).toEqual([{ lotId: downLot, lotCode: expect.any(String) as string, state: expect.any(String) as string }]);
    // Reads need a session.
    const anon = w.gmp.browser();
    expect(refusalOf(await anon.call(routes.release.suspended, {})).status).toBe(401);
    expect(refusalOf(await anon.call(routes.release.afterRelease, { params: { lotId } })).status).toBe(401);
    expect(v.markets[0]!.signable.recall).toBe(`${lotId}/IN/RECALL/1`);
    expect(v.disposalGate.ready).toBe(false);

    const operator = await actorOf(w.gmp, 'qaInvestigator');
    await withCommand(w.gmp.db.app, { ...operator, correlationId: randomUUID() }, async (c) => {
      const d = (await c.query<{ r: { deviationId: string } }>('select site.raise_deviation($1::jsonb) as r', [
        JSON.stringify({ kind: 'DEVIATION', title: 'Complaint after release', classification: 'MAJOR', riskRationale: 'Market complaint on appearance' }),
      ])).rows[0]!.r;
      await c.query("select site.link_deviation($1, 'LOT', $2)", [d.deviationId, lotId]);
    });
    v = await view();
    expect(v.manufacturerState).toBe('RELEASE_SUSPENDED');
    expect(v.causes.map((c) => [c.market, c.causeKind, c.via.kind, c.priorState, c.covered])).toEqual([['IN', 'DEVIATION', 'LOT', 'RELEASED', false]]);
    expect(v.causes[0]!.problem).toMatch(/a cause is resolved once its deviation is closed/);
    expect(v.markets[0]).toMatchObject({ state: 'RELEASE_SUSPENDED', priorState: 'RELEASED' });
    expect(v.markets[0]!.gates.reconfirm.ready).toBe(false);
    expect(v.markets[1]).toMatchObject({ market: 'US', priorState: null });
    expect(v.tasks.map((t) => [t.kind, t.ownerRole, t.status])).toEqual([['RECALL_ASSESSMENT', 'AUTHORISED_PERSON', 'OPEN']]);
    expect(v.stockBlocks.map((b) => [b.kind, b.deliveredAt])).toEqual([['BLOCK', null]]);
    const queue = valueOf(await ap.call(routes.release.suspended, {}));
    expect(queue.lots.find((l) => l.lotId === lotId)).toMatchObject({ manufacturerState: 'RELEASE_SUSPENDED', suspendedMarkets: ['IN'], openTask: true });
    const unknown = randomUUID();
    expect(refusalOf(await ap.call(routes.release.afterRelease, { params: { lotId: unknown } }))).toMatchObject({
      status: 404, code: 'EBMR-REL-010', why: expect.stringContaining(unknown) as string, whatYouCanDo: [expect.stringMatching(/./) as string],
    });
  });

  it('[L-19][IN-05] the AP recalls the suspended lot through the ceremony (with a reason); a recall without one signs nothing; the lot register moves with it', async (ctx) => {
    if (!mapped) {
      // The ceremony mapping of release_suspension arrives with slice 5b's single re-creation (tablets 1199).
      ctx.skip();
      return;
    }
    // Each after-release act names the market's next decision record, its own meaning and the state the AP sees now.
    const act = (a: 'RECONFIRM' | 'REJECT_AFTER_RELEASE', input: ReleaseActInput): SignableAction => ({ kind: 'RELEASE_ACT', act: a, lotId, input });
    expect(await describeAction(ap, act('RECONFIRM', { market: 'IN', expectedEpoch: '0'.repeat(64), text: 'Impact assessed' }))).toMatchObject({
      aggregateType: 'release_suspension', aggregateId: `${lotId}/IN/RECONFIRM/1`, meaning: 'RELEASE_RECONFIRMED', expectedState: 'RELEASE_SUSPENDED',
    });
    expect(await describeAction(ap, act('REJECT_AFTER_RELEASE', { market: 'IN', reason: { code: 'OOS', text: 'Confirmed out of specification' } }))).toMatchObject({
      aggregateType: 'release_suspension', aggregateId: `${lotId}/IN/REJECT_AFTER_RELEASE/1`, meaning: 'REJECTED_AFTER_RELEASE', expectedState: 'RELEASE_SUSPENDED',
    });
    expect(await describeAction(ap, recall({ market: 'IN', reason: { code: 'COMPLAINT', text: 'x' } }))).toMatchObject({ aggregateId: `${lotId}/IN/RECALL/1`, meaning: 'RECALLED' });
    expect(await describeAction(ap, recall({ reason: { code: 'COMPLAINT', text: 'x' } }))).toMatchObject({ aggregateId: `${lotId}//RECALL/1` });
    expect(refusalOf(await signAction(w.gmp, ap, 'qcuAuthoriser', act('RECONFIRM', { market: 'IN', expectedEpoch: '0'.repeat(64) })))?.code).toBe('EBMR-API-ACT-INPUT');
    const without = await signAction(w.gmp, ap, 'qcuAuthoriser', recall({ market: 'IN' }));
    expect(refusalOf(without)?.code).toBe('EBMR-API-ACT-INPUT');
    const r = await signAction(w.gmp, ap, 'qcuAuthoriser', recall({ market: 'IN', reason: { code: 'COMPLAINT', text: 'Complaint cluster: tablets crumbling in the blister' } }));
    expect(r.ok ? null : refusalOf(r)).toBeNull();
    const v = await view();
    expect(v.manufacturerState).toBe('RECALLED');
    expect(v.decisions.map((d) => [d.market, d.act, d.toState])).toEqual([['IN', 'RECALL', 'RECALLED']]);
    expect(v.decisions[0]!.by).toMatchObject({ legalName: 'Shalini Kapoor', role: 'AUTHORISED_PERSON' });
    expect(v.tasks[0]!.status).toBe('CLOSED');
    expect(v.disposalGate.ready).toBe(true);
    const st = (await w.gmp.db.admin.query<{ s: string }>("select state as s from platform.aggregate_state where aggregate_type = 'material_lot' and aggregate_id = $1", [lotId])).rows[0]!.s;
    expect(st).toBe('RECALLED');
  });

  it('[PR-46][IN-05] QA disposes of the recalled lot through the ceremony (a witnessed destruction) and an independent witness completes it; the view shows the record awaiting its witness, then recorded', async (ctx) => {
    if (!mapped) {
      ctx.skip();
      return;
    }
    const [qa, witness] = await Promise.all([w.gmp.asPersona('qaInvestigator'), w.gmp.asPersona('qa1')]);
    const details: ReleaseActInput = { disposalRoute: 'WITNESSED_DESTRUCTION', disposalQuantity: '1000', disposalReference: 'DR-2026-0011', text: 'Incinerated by the licensed contractor' };
    const dispose: SignableAction = { kind: 'RELEASE_ACT', act: 'DISPOSAL', lotId, input: details };
    const d = await describeAction(qa, dispose);
    expect(d).toMatchObject({ aggregateType: 'disposal', meaning: 'DISPOSAL_RECORDED' });
    expect(d.aggregateId).toMatch(new RegExp(`^${lotId}/[0-9a-f]{64}$`));
    expect(refusalOf(await signAction(w.gmp, qa, 'qaInvestigator', { ...dispose, input: { disposalRoute: 'WITNESSED_DESTRUCTION' } }))?.code).toBe('EBMR-API-ACT-INPUT');
    const r = await signAction(w.gmp, qa, 'qaInvestigator', dispose);
    expect(r.ok ? null : refusalOf(r)).toBeNull();
    let v = await view();
    expect(v.disposal).toMatchObject({
      route: 'WITNESSED_DESTRUCTION', state: 'AWAITING_WITNESS', quantity: '1000', reference: 'DR-2026-0011', text: 'Incinerated by the licensed contractor', returnTo: null,
      reprocessingRef: null, aggregateId: d.aggregateId, performedBy: { legalName: 'Divya Menon' }, witnessedBy: null, witnessedAt: null, witnessSignatureId: null,
    });
    expect(v.disposalGate.ready).toBe(false);
    const disposalId = v.disposal!.disposalId;
    // The witness signs the same record (its id read from the database), with nothing but the disposal named.
    const witnessAct: SignableAction = { kind: 'RELEASE_ACT', act: 'DISPOSAL', lotId, input: { disposalId } };
    expect(await describeAction(witness, witnessAct)).toMatchObject({ aggregateType: 'disposal', aggregateId: d.aggregateId, meaning: 'DESTRUCTION_WITNESSED', expectedState: 'AWAITING_WITNESS' });
    // A disposal of no such record names no record to sign.
    expect(await describeAction(witness, { ...witnessAct, input: { disposalId: randomUUID() } })).toMatchObject({ aggregateId: `${lotId}/no-disposal` });
    const wr = await kioskSign(witness, 'qa1', witnessAct);
    expect(wr.ok ? null : refusalOf(wr)).toBeNull();
    v = await view();
    expect(v.disposal).toMatchObject({ disposalId, state: 'RECORDED', witnessedBy: { legalName: 'Fatima Sheikh' } });
    expect(v.disposal!.witnessSignatureId).toBeTruthy();
    expect(v.disposal!.witnessedAt).toBeTruthy();
    const st = (await w.gmp.db.admin.query<{ s: string }>("select state as s from platform.aggregate_state where aggregate_type = 'material_lot' and aggregate_id = $1", [lotId])).rows[0]!.s;
    expect(st).toBe('DESTROYED');
  });
});

apps/tablets-server/test/release/market-.source:
/**
 * The market routes and acts over HTTP (Phase 4 slice 4a; contract ns/release.ts; recipe-core 0820 to 0824, tablets 1180,
 * 1189): the lot's market view and market-add evaluations, a market added through the ceremony (its sequence read by the
 * server), the two-row release ceremony (D-P4-5) refused whole when the database refuses, and the intake of a structured
 * certification message whose Ed25519 signature the database verifies, every message acknowledged (DI-39). The finished
 * lot is posted as the edition's definer posts it; its batch is a real GMP batch, issued and not reviewed.
 */
import { generateKeyPairSync, randomUUID, sign as edSign } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { sha256Hex } from '@ebmr/expr';
import { routes, type SignableAction } from '@ebmr/api-contract';
import { withCommand } from '@ebmr/kernel';
import { refusalOf, valueOf } from '../esig/support.ts';
import { actorOf, startGmpBatchWorld, type GmpBatchWorld } from '../support/gmp-world.ts';
import type { TestBrowser } from '../support/harness.ts';
import { credentialsOf, describeAction, signAction } from '../support/signed-acts.ts';

let w: GmpBatchWorld;
let ap: TestBrowser;
let qa: TestBrowser;
let batchId: string;
let lotId: string;
let lotCode: string;
let batchNumber: string;
const keys = generateKeyPairSync('ed25519');
const importerCode = `EUIMP-${randomUUID().slice(0, 6).toUpperCase()}`;

beforeAll(async () => {
  w = await startGmpBatchWorld();
  const issuer = await w.gmp.asPersona('issuer');
  [ap, qa] = await Promise.all([w.gmp.asPersona('qcuAuthoriser'), w.gmp.asPersona('qaInvestigator')]);
  batchId = await w.issued(issuer);
  batchNumber = (await w.gmp.db.admin.query<{ n: string }>('select batch_number as n from recipe.batch_execution where id = $1', [batchId])).rows[0]!.n;
  const stores = await actorOf(w.gmp, 'stores');
  lotId = await withCommand(w.gmp.db.admin, { ...stores, correlationId: randomUUID() }, async (c) =>
    (await c.query<{ id: string }>('select site.create_finished_lot($1::jsonb) as id', [
      JSON.stringify({ batchId, batchNumber, edition: 'TABLETS', siteCode: 'SITE-1', productCode: w.content.header.product.code, productName: 'Market route product',
                       strength: '500 mg', markets: ['IN'], quantity: '1000', unit: 'units', expiresAt: '2029-06-30T23:59:59Z' }),
    ])).rows[0]!.id,
  );
  lotCode = (await w.gmp.db.admin.query<{ c: string }>('select lot_code as c from site.material_lot where id = $1', [lotId])).rows[0]!.c;
  // TEST FIXTURE: the importer and its message key (QA's signed EU_IMPORTER_APPROVED act is proven in recipe-core's tests).
  const spki = keys.publicKey.export({ type: 'spki', format: 'der' });
  await withCommand(w.gmp.db.admin, { ...stores, correlationId: randomUUID() }, async (c) => {
    const { rows } = await c.query<{ id: string }>(
      "insert into recipe.eu_importer (code, name, technical_agreement_ref, mia_number, public_key, signature_id, person_id, account_id) values ($1, 'Example Pharma Import GmbH', 'TA-2026-007', 'DE-MIA-2024-118', $2, gen_random_uuid(), $3, $4) returning id",
      [importerCode, spki.subarray(spki.length - 32), stores.personId, stores.accountId],
    );
    await c.query('insert into recipe.eu_importer_product (product_code, importer_id) values ($1, $2)', [w.content.header.product.code, rows[0]!.id]);
  });
}, 600_000);
afterAll(async () => {
  await w?.close();
});

const codeOf = (r: Awaited<ReturnType<typeof signAction>>): string => (r.ok ? 'ok' : (refusalOf(r)?.why.match(/EBMR-[A-Z]+-\d{3}/)?.[0] ?? refusalOf(r)?.code ?? 'refused'));

/** The two-row ceremony as a screen runs it: a challenge for each record, the credentials entered once. */
async function signTwoRows(b: TestBrowser, personaKey: string, action: SignableAction, withCompanion = true) {
  const d = await describeAction(b, action);
  const challenge = async (aggregateType: string, aggregateId: string, meaning: string) => {
    const preview = valueOf(await b.call(routes.esig.content, { query: { aggregateType, aggregateId, intent: meaning } }));
    return valueOf(await b.call(routes.esig.createChallenge, {
      body: { aggregateType, aggregateId, contentVersion: preview.contentVersion, meaning, clientContentHash: sha256Hex(preview.canonicalText), action },
    }));
  };
  const first = await challenge(d.aggregateType, d.aggregateId, d.meaning ?? '');
  const second = withCompanion && d.companion ? await challenge(d.companion.aggregateType, d.companion.aggregateId, d.companion.meaning) : null;
  const body = { challengeId: first.challengeId, credentials: credentialsOf(w.gmp, personaKey), action, ...(second ? { companionChallengeId: second.challengeId } : {}) };
  return b.call(routes.esig.sign, { body: { ...body, proof: await b.proof('POST', '/api/esig/sign', body) } });
}

async function message(fields: Record<string, unknown>, opts: { badKey?: boolean } = {}) {
  const text = JSON.stringify({ format: 'ebmr.qp-certification.v1', messageId: `MSG-${randomUUID()}`, importerCode, lotCode, batchNumber, productCode: w.content.header.product.code,
                                outcome: 'CERTIFIED', certifier: { name: 'Dr. Lena Vogel', miaNumber: 'DE-MIA-2024-118' }, certifiedAt: new Date().toISOString(), ...fields });
  const key = opts.badKey ? generateKeyPairSync('ed25519').privateKey : keys.privateKey;
  const body = { message: text, signature: edSign(null, Buffer.from(text, 'utf8'), key).toString('base64') };
  return qa.call(routes.release.qpMessage, { body });
}

describe('market routes over HTTP (outline 3.3.3, 5.2.6)', () => {
  it('[meta] an India-only lot has no export disposition; the market-add evaluations of the lot and its batch answer; the importers are listed; an unknown lot is 404', async () => {
    const view = valueOf(await qa.call(routes.release.markets, { params: { lotId } }));
    expect(view).toMatchObject({ lotId, manufacturerState: 'NOT_READY', markets: ['IN'], dispositions: [] });
    const lotEval = valueOf(await qa.call(routes.release.marketAdd, { params: { lotId }, query: { market: 'US' } }));
    expect(lotEval).toMatchObject({ subjectKind: 'LOT', subjectId: lotId, market: 'US' });
    expect(lotEval.items.map((i) => i.id)).toEqual(['MA.MBR_AUTHORISATION', 'MA.IDENTITY_ROUTE', 'MA.RELEASE_TESTS', 'MA.RESERVE_SAMPLES']);
    const batchEval = valueOf(await qa.call(routes.release.batchMarketAdd, { params: { batchId }, query: { market: 'EU' } }));
    expect(batchEval.items.map((i) => i.id)).toEqual(['MA.MBR_AUTHORISATION', 'MA.IDENTITY_ROUTE']);
    expect(refusalOf(await qa.call(routes.release.markets, { params: { lotId: randomUUID() } })).status).toBe(404);
    expect(refusalOf(await qa.call(routes.release.batchMarketAdd, { params: { batchId: randomUUID() }, query: { market: 'US' } })).status).toBe(404);
    const imp = valueOf(await qa.call(routes.release.importers)).importers.find((i) => i.code === importerCode);
    expect(imp).toMatchObject({ miaNumber: 'DE-MIA-2024-118', products: [w.content.header.product.code] });
    expect(imp?.keyFingerprint).toMatch(/^[0-9a-f]{64}$/);
  });

  it('[INV-43] QA adds the US to the lot under a change record through the ceremony: the server reads the change\'s sequence, the evaluation is stored and shown; the AP cannot', async () => {
    const changeRecordId = (await w.gmp.db.admin.query<{ id: string }>('select id from recipe.change_record order by recorded_at limit 1')).rows[0]!.id;
    const add: SignableAction = { kind: 'RELEASE_ACT', act: 'MARKET_ADD', lotId, input: { market: 'US', changeRecordId } };
    const d = await describeAction(qa, add);
    expect(d).toMatchObject({ aggregateType: 'market_change', aggregateId: `LOT/${lotId}/ADD/US/1`, meaning: 'MARKET_ADDED', expectedState: 'NOT_IN_SET' });
    expect(codeOf(await signAction(w.gmp, ap, 'qcuAuthoriser', add))).not.toBe('ok');
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', { ...add, input: { market: 'US' } }))).toBe('EBMR-API-ACT-INPUT');
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', add))).toBe('ok');
    const view = valueOf(await qa.call(routes.release.markets, { params: { lotId } }));
    expect(view.markets).toEqual(['IN', 'US']);
    const us = view.dispositions.find((x) => x.market === 'US');
    expect(us?.changes).toHaveLength(1);
    expect(us?.changes[0]).toMatchObject({ change: 'ADD', subjectKind: 'LOT', removedAfterFailure: false, by: { legalName: 'Divya Menon' } });
    expect(us?.changes[0]?.evaluation?.items.length).toBeGreaterThan(0);
    expect(us?.marketAdd).not.toBeNull();
    expect(['NOT_READY', 'INELIGIBLE']).toContain(us?.state);
    expect(us?.gates.release.ready).toBe(false);
    // The next change of the market is the second in the sequence.
    expect((await describeAction(qa, { kind: 'RELEASE_ACT', act: 'MARKET_REMOVE', lotId, input: { market: 'US', deviationId: randomUUID() } })).aggregateId).toBe(`LOT/${lotId}/REMOVE/US/2`);
  });

  it('the two-row release (D-P4-5): the server names the companion record; without its challenge nothing is signed, and an AP who does not hold the QCU permission cannot open the US challenge', async () => {
    const action: SignableAction = { kind: 'RELEASE_ACT', act: 'MANUFACTURER_RELEASE', lotId, input: { expectedEpoch: 'a'.repeat(64), usExpectedEpoch: 'b'.repeat(64) } };
    const d = await describeAction(ap, action);
    expect(d.companion).toMatchObject({ aggregateType: 'us_disposition', aggregateId: `${lotId}/RELEASE`, meaning: 'US_DISPOSITION' });
    expect((await describeAction(ap, { ...action, input: { expectedEpoch: 'a'.repeat(64) } })).companion).toBeUndefined();
    const count = async () => Number((await w.gmp.db.admin.query<{ n: string }>("select count(*) as n from esig.signature where aggregate_id like $1 || '%'", [lotId])).rows[0]!.n);
    const before = await count();
    // The seed's AP holds no RELEASE.US_DISPOSITION: the US record is not even shown for signing.
    await expect(signTwoRows(ap, 'qcuAuthoriser', action)).rejects.toThrow(/may not sign US_DISPOSITION/);
    // The action asks for two rows: one challenge alone signs nothing.
    const one = await signTwoRows(ap, 'qcuAuthoriser', action, false).catch((e: Error) => e);
    expect(one instanceof Error || !one.ok).toBe(true);
    expect(await count()).toBe(before);
    // Quick review MEDIUM 4: the database act itself needs RELEASE.US_DISPOSITION of the actor, whatever signatures it is given.
    const apActor = await actorOf(w.gmp, 'qcuAuthoriser');
    const direct = await withCommand(w.gmp.db.app, { ...apActor, correlationId: randomUUID() }, (c) =>
      c.query('select recipe.record_release_with_us_disposition($1, $2, $3, $4, $5)', [lotId, randomUUID(), randomUUID(), 'a'.repeat(64), 'b'.repeat(64)]),
    ).then(() => 'ok', (e: Error) => e.message);
    expect(direct).toMatch(/EBMR-IAM-040 .*RELEASE\.US_DISPOSITION/);
  });
});

describe('the structured certification message (DI-39)', () => {
  it('[DI-39] the database verifies the importer\'s signature and acknowledges every message: a forged one, an unknown importer and a lot not awaiting certification are refused with their reason; a resend gets its first acknowledgement', async () => {
    const forged = valueOf(await message({}, { badKey: true }));
    expect(forged).toMatchObject({ outcome: 'REFUSED', certificationId: null });
    expect(forged.reason).toMatch(/EBMR-DSP-082/);
    const unknown = valueOf(await message({ importerCode: 'EUIMP-NOBODY' }));
    expect(unknown.reason).toMatch(/EBMR-DSP-081/);
    const notAwaiting = valueOf(await message({}));
    expect(notAwaiting).toMatchObject({ outcome: 'REFUSED', lotId });
    expect(notAwaiting.reason).toMatch(/EBMR-DSP-03[13]/);
    // Nothing reached the register; every message has its acknowledgement.
    expect((await w.gmp.db.admin.query('select 1 from recipe.qp_certification where lot_id = $1', [lotId])).rows).toEqual([]);
    const acks = await w.gmp.db.admin.query<{ n: string }>('select count(*) as n from recipe.qp_message_ack where message_sha256 = any ($1)', [[forged.messageSha256, unknown.messageSha256, notAwaiting.messageSha256]]);
    expect(Number(acks.rows[0]!.n)).toBe(3);
    // The application role cannot write the register or an acknowledgement, nor take a message in without the check.
    expect(await w.gmp.db.app.query("insert into recipe.qp_message_ack (message_id, message_sha256, outcome, reason, person_id, account_id) values ('x', $1, 'REFUSED', 'x', gen_random_uuid(), gen_random_uuid())", ['0'.repeat(64)]).then(() => 'ok', (e: Error) => e.message)).toMatch(/permission denied/);
    expect(await w.gmp.db.app.query("select recipe.take_qp_message('{}', true)").then(() => 'ok', (e: Error) => e.message)).toMatch(/permission denied/);
  });
});

